// Dev: which mods this session runs from a folder the
// person works in, how each is loaded, what its last validate and test said,
// what the session reported while hot-reloading it, and how to share it.
// services/dev.ts gathers the inputs; every decision lives here.

import type { DevFailures, DevHow, DevRow, Job, JobState, Origin } from '../../types/index.d.ts'
import type { InstalledEntry } from './cli-results.ts'
import { safeSegments } from './detector.ts'
import { isPluginName, parseAbsolutePath, splitPluginId } from './ids.ts'
import { isRecord, parseJson, str } from './json.ts'
import { originOf, rootOf, runningVersion } from './mods.ts'
import { sanitize } from './sanitize.ts'

/** A Dev row's Button key: what `ui.focus` and `ui.press` name. */
export const DEV_PREFIX = 'dev:'
export const devKey = (key: string): string => `${DEV_PREFIX}${key}`
export const devOfKey = (key: string | undefined): string | undefined =>
  key?.startsWith(DEV_PREFIX) === true ? key.slice(DEV_PREFIX.length) : undefined

/** The order Dev lists its sections in. */
export const DEV_SECTIONS: readonly DevHow[] = [
  'session-folder',
  'plugin-dir',
  'env-dir',
  'skills-dir',
  'folder-marketplace',
]

/** A row's few words for how it is loaded (from 60 columns). */
export const HOW_SHORT: Readonly<Record<DevHow, string>> = {
  'session-folder': 'session',
  'plugin-dir': '--plugin-dir',
  'env-dir': 'env dirs',
  'skills-dir': 'skills',
  'folder-marketplace': 'folder mkt',
}

/** How it is loaded, in the detail. */
export const SECTION_LABEL: Readonly<Record<DevHow, string>> = {
  'session-folder': "This session's mods folder",
  'plugin-dir': 'Loaded with --plugin-dir',
  'env-dir': 'From CLAUDE_CODE_PLUGIN_DIRS',
  'skills-dir': 'Your skills folder',
  'folder-marketplace': 'Folder marketplaces',
}

/** How an edit to its files reaches this session (every action says when it applies). */
export const appliesOf = (how: DevHow): string =>
  how === 'folder-marketplace'
    ? 'Its folder is read again at the next plugin reload (l).'
    : 'Saving a file there reloads it in this session.'

/** How to stop loading it, where the CLI can't; undefined when Installed toggles it. */
export const stopLoadingOf = (row: DevRow): string | undefined => {
  switch (row.how) {
    case 'session-folder':
      return 'It is loaded for this session only.'
    case 'plugin-dir':
      return 'To stop loading it, leave --plugin-dir out of your launch command.'
    case 'env-dir':
      return 'To stop loading it, take its folder out of CLAUDE_CODE_PLUGIN_DIRS and restart.'
    default:
      return undefined
  }
}

const DEV_ORIGINS: ReadonlyMap<Origin, DevHow> = new Map([
  ['env-dir', 'env-dir'],
  ['skills-dir', 'skills-dir'],
  ['folder-marketplace', 'folder-marketplace'],
])

/** A plugin the CLI lists, and whether validate found a hooks module (undefined: it couldn't read it). */
export type Listed = { readonly entry: InstalledEntry; readonly mod: boolean | undefined }

/** A plugin folder modmgr found, with what its manifest says. */
export type Found = { readonly name: string; readonly path: string; readonly version?: string }

export type DevSources = {
  readonly listed: readonly Listed[]
  /** The plugins that registered a command (`$.command.list()`), by name or id. */
  readonly commandPlugins: readonly string[]
  /** This session's mods folder's plugins. */
  readonly sessionFolder: readonly Found[]
  /** The folders found for plugins the CLI doesn't list (`--plugin-dir`), by name. */
  readonly located: ReadonlyMap<string, Found>
}

/** The name part of a plugin as a command names it (`modmgr`, `spawner@inline`). */
const bareName = (plugin: string): string => {
  const at = plugin.indexOf('@')
  return at < 0 ? plugin : plugin.slice(0, at)
}

/**
 * The plugins this session runs that the CLI doesn't list, whose folder to
 * look for: what `--plugin-dir` loaded (the flag isn't inherited by a
 * child). A plugin that registered a command, or one the session reported
 * failing. Built-in plugins register commands too (`cc-plugin-diff`, found
 * live), so a name becomes a row only once its folder is found.
 */
export const unlistedPlugins = (
  commandPlugins: readonly string[],
  failing: readonly string[],
  known: ReadonlySet<string>,
): string[] =>
  [...new Set([...commandPlugins.map(bareName), ...failing])]
    .filter(name => isPluginName(name) && !known.has(name))
    .sort()

const byPlace = (a: DevRow, b: DevRow): number =>
  DEV_SECTIONS.indexOf(a.how) - DEV_SECTIONS.indexOf(b.how) ||
  a.name.localeCompare(b.name) ||
  a.key.localeCompare(b.key)

/**
 * Dev's rows, by section then name: listed plugins loaded from a folder the
 * person edits (not a plain plugin; one validate couldn't read stays, since a
 * broken mod is what Dev is for), this session's mods folder, and the
 * `--plugin-dir` plugins whose folder was found (`located`).
 */
export const devRowsOf = (sources: DevSources): DevRow[] => {
  const rows: DevRow[] = []
  const listedNames = new Set(sources.listed.map(({ entry }) => splitPluginId(entry.id).name))
  for (const { entry, mod } of sources.listed) {
    const how = DEV_ORIGINS.get(originOf(entry))
    const path = rootOf(entry)
    if (how === undefined || mod === false || path === undefined) continue
    const version = runningVersion(entry)
    rows.push({
      key: path,
      name: splitPluginId(entry.id).name,
      how,
      id: entry.id,
      path,
      enabled: entry.enabled,
      ...(version === undefined ? {} : { version }),
    })
  }
  // A plugin that registered a command is loaded (a session folder's may not be yet).
  const loaded = new Set(sources.commandPlugins.map(bareName))
  const sessionNames = new Set(sources.sessionFolder.map(found => found.name))
  for (const found of sources.sessionFolder) {
    // A folder the CLI lists under another heading is said once, there.
    if (rows.some(row => row.path === found.path)) continue
    rows.push({
      key: found.path,
      ...rowOfFound(found),
      how: 'session-folder',
      ...(loaded.has(found.name) ? { enabled: true } : {}),
    })
  }
  for (const [name, found] of sources.located) {
    if (listedNames.has(name) || sessionNames.has(name) || found.name !== name) continue
    if (rows.some(row => row.path === found.path)) continue
    rows.push({
      key: found.path,
      ...rowOfFound(found),
      how: 'plugin-dir',
      ...(loaded.has(name) ? { enabled: true } : {}),
    })
  }
  return rows.sort(byPlace)
}

const rowOfFound = (found: Found): Pick<DevRow, 'name' | 'path' | 'version'> => ({
  name: found.name,
  path: found.path,
  ...(found.version === undefined ? {} : { version: found.version }),
})

/** A `plugin.json`'s name and version, when it names a plugin. */
export const manifestOf = (text: string): { name: string; version?: string } | undefined => {
  const value = parseJson(text)
  if (!isRecord(value)) return undefined
  const name = str(value, 'name')
  if (name === undefined || !isPluginName(name)) return undefined
  const version = str(value, 'version')
  return version === undefined ? { name } : { name, version: version.slice(0, 64) }
}

/**
 * The folder a `marketplace.json` gives plugin `name`, relative to the
 * marketplace's root (`''` for the root itself); undefined when it doesn't
 * list it, or lists it at a path that is absolute or climbs.
 */
export const marketplaceFolderOf = (text: string, name: string): string | undefined => {
  const value = parseJson(text)
  if (!isRecord(value) || !Array.isArray(value.plugins)) return undefined
  const entry = value.plugins.find(plugin => isRecord(plugin) && plugin.name === name)
  if (!isRecord(entry) || typeof entry.source !== 'string') return undefined
  const segments = safeSegments(entry.source)
  return segments?.map(decodeURIComponent).join('/')
}

/** `a/b` joined under `root`, or `root` itself for `''`. */
export const joinPath = (root: string, relative: string): string => {
  const head = root.replace(/\/+$/, '')
  return relative === '' ? head : `${head}/${relative}`
}

const SESSION_ID = /^[A-Za-z0-9_-]{1,128}$/

/** A session id that is one plain path segment. */
export const isSessionId = (value: string): boolean => SESSION_ID.test(value)

/**
 * This session's mods folder: `<config dir>/dev-mods/<session id>`, the config
 * dir being `CLAUDE_CONFIG_DIR` or `~/.claude`. Undefined when neither is an
 * absolute path or the session id isn't one plain segment.
 */
export const sessionFolderOf = (how: {
  readonly configDir: string | undefined
  readonly home: string | undefined
  readonly sessionId: string
}): string | undefined => {
  if (!SESSION_ID.test(how.sessionId)) return undefined
  const config = configDirOf(how.configDir, how.home)
  return config === undefined ? undefined : joinPath(config, `dev-mods/${how.sessionId}`)
}

/** Claude Code's config dir: `CLAUDE_CONFIG_DIR`, else `~/.claude`; undefined unless absolute. */
export const configDirOf = (
  configDir: string | undefined,
  home: string | undefined,
): string | undefined => {
  const config =
    configDir !== undefined && configDir !== ''
      ? configDir
      : home === undefined
        ? undefined
        : joinPath(home, '.claude')
  return config?.startsWith('/') === true ? config : undefined
}

/** The row Dev shows as selected and acts on: the selection when listed, else the first. */
export const devRowOf = (
  selected: string | undefined,
  rows: readonly DevRow[],
): DevRow | undefined => rows.find(row => row.key === selected) ?? rows[0]

/**
 * The selection once rows change: the row shown selected before, while it is
 * still listed, so a row that joins at the top (a failing folder) never takes
 * the selection from under the focus ring (found live).
 */
export const keptSelection = (
  selected: string | undefined,
  before: readonly DevRow[],
  after: readonly DevRow[],
): string | undefined => {
  const shown = devRowOf(selected, before)?.key
  return after.some(row => row.key === shown) ? shown : after[0]?.key
}

// ---- what ran ----------------------------------------------------------------

export type DevRunKind = 'validate' | 'test'

/** The newest validate or test of `path` in the queue. */
export const lastRun = (jobs: readonly Job[], kind: DevRunKind, path: string): Job | undefined =>
  jobs.findLast(job => job.kind === kind && job.args?.path === path)

export type RunMark = { readonly text: string; readonly tone: 'busy' | 'ok' | 'bad' | 'muted' }

const BUSY: ReadonlySet<JobState> = new Set(['queued', 'running'])

/** A row's short mark for its last validate: `✓`, `✓ 2 warnings`, `✗ 3`, `…`, or nothing yet. */
export const validateMark = (job: Job | undefined): RunMark | undefined => {
  if (job === undefined) return undefined
  if (BUSY.has(job.state)) return { text: 'validating…', tone: 'busy' }
  const report = job.report
  if (job.state === 'ok') {
    const warnings = report?.warnings ?? 0
    return warnings === 0
      ? { text: '✓ valid', tone: 'ok' }
      : { text: `✓ ${warnings} ${warnings === 1 ? 'warning' : 'warnings'}`, tone: 'ok' }
  }
  if (job.state === 'failed' && report !== undefined) {
    return { text: `✗ ${report.errors} ${report.errors === 1 ? 'error' : 'errors'}`, tone: 'bad' }
  }
  return job.state === 'failed'
    ? { text: '✗ validate failed', tone: 'bad' }
    : { text: `validate ${job.state}`, tone: 'muted' }
}

/** A row's short mark for its last test run. */
export const testMark = (job: Job | undefined): RunMark | undefined => {
  if (job === undefined) return undefined
  if (BUSY.has(job.state)) return { text: 'testing…', tone: 'busy' }
  if (job.state === 'ok') return { text: '✓ tests', tone: 'ok' }
  if (job.state === 'failed') return { text: '✗ tests', tone: 'bad' }
  return { text: `tests ${job.state}`, tone: 'muted' }
}

// ---- what the session reported --------------------------------------------------

const NOTICE = /^([a-z0-9][a-z0-9._-]{0,63})(?:@[a-z0-9][a-z0-9._-]{0,63})?: ([\s\S]+)$/
/** The words the engine's notices use for a hook or module that didn't work. */
const FAILURE = /\b(?:fail(?:s|ed)?|refused|skipped|threw|not loaded|did not load|errors?)\b/i

/**
 * The plugin folder a hooks file's path names (`: <folder>/hooks/<file>`), the
 * folder allowed to hold spaces.
 */
const HOOKS_FILE = /:\s(\/.+?)\/hooks\/[^\s/:`'"]+/
/**
 * The notices that name a module's file (`broken: reload failed, the previous
 * version stays loaded: <folder>/hooks/register.ts, …`): only these say where a plugin is.
 */
const NAMES_FOLDER = /\b(?:reload failed|did not load)\b/

export type Failure = { readonly name: string; readonly reason: string; readonly folder?: string }

/**
 * A session notice that says a plugin's hook or module failed:
 * `<plugin>: <what happened>` (the engine's reference, §Drawing), with the plugin's
 * folder when the notice names a file of its hooks (a module that didn't
 * load or reload does). Undefined for any other notice (a reload's line, a
 * command's output).
 */
export const failureOf = (text: string): Failure | undefined => {
  const match = NOTICE.exec(text.trim())
  const name = match?.[1]
  const reason = match?.[2]
  if (name === undefined || reason === undefined || !FAILURE.test(reason)) return undefined
  const folder = NAMES_FOLDER.test(reason) ? HOOKS_FILE.exec(reason)?.[1] : undefined
  const checked = folder === undefined ? undefined : parseAbsolutePath(folder)
  return {
    name,
    reason: sanitize(reason, { max: 300 }),
    ...(checked?.ok === true ? { folder: checked.value } : {}),
  }
}

/** Counts one more failure of `name`. */
export const recordFailure = (
  failures: Readonly<Record<string, DevFailures>>,
  failure: Failure,
  at: number,
): Record<string, DevFailures> => {
  const folder = failure.folder ?? failures[failure.name]?.folder
  return {
    ...failures,
    [failure.name]: {
      count: (failures[failure.name]?.count ?? 0) + 1,
      lastReason: failure.reason,
      lastAt: at,
      ...(folder === undefined ? {} : { folder }),
    },
  }
}

// ---- sharing (the engine's reference, §Sharing a mod) --------------------------

/** `owner/repo` of a GitHub remote (https, ssh or scp form), or undefined. */
export const githubRepoOf = (remote: string | null | undefined): string | undefined => {
  if (remote === null || remote === undefined) return undefined
  const match =
    /^(?:https:\/\/github\.com\/|git@github\.com:|ssh:\/\/git@github\.com\/)([A-Za-z0-9][A-Za-z0-9-]{0,38})\/([A-Za-z0-9._-]{1,100}?)(?:\.git)?\/?$/.exec(
      remote.trim(),
    )
  const owner = match?.[1]
  const repo = match?.[2]
  return owner === undefined || repo === undefined ? undefined : `${owner}/${repo}`
}

/** Whether `path` is `root` or inside it. */
export const isInside = (path: string, root: string): boolean => {
  const head = root.replace(/\/+$/, '')
  return path === head || path.startsWith(`${head}/`)
}

export type Share = {
  /** What another person types: `/plugin install <mod> --marketplace <owner>/<repo>`. */
  readonly line: string
  /** Whether `line` names a real repository (else `<owner>/<repo>` stands in it). */
  readonly complete: boolean
  /** The marketplace file to write beside `plugin.json`, when none lists the mod. */
  readonly snippet?: string
  readonly notes: readonly string[]
}

/**
 * How to share a dev mod: the one install line, and what is missing for it to
 * work (a marketplace file listing the mod, a GitHub repository, a folder kept
 * outside this session's mods folder).
 */
export const shareOf = (
  row: Pick<DevRow, 'name' | 'how'>,
  how: {
    readonly repo: string | undefined
    readonly listed: boolean
    /** The mod's folder relative to the repository's root (`./`, `./plugin`). */
    readonly source: string
  },
): Share => {
  const repo = how.repo ?? '<owner>/<repo>'
  const notes: string[] = []
  if (row.how === 'session-folder') {
    notes.push(
      "Copy it out of this session's mods folder to a folder you keep, and make that the repository.",
    )
  }
  if (how.repo === undefined) {
    notes.push('Push its folder to a GitHub repository; <owner>/<repo> is that repository.')
  }
  const snippet = how.listed
    ? undefined
    : JSON.stringify(
        {
          name: row.name,
          owner: { name: '<your name>' },
          plugins: [{ name: row.name, source: how.source }],
        },
        null,
        2,
      )
  if (snippet !== undefined) {
    notes.push(
      how.source === './'
        ? 'Write this as .claude-plugin/marketplace.json beside its plugin.json:'
        : "Write this as .claude-plugin/marketplace.json at the repository's root:",
    )
  }
  return {
    line: `/plugin install ${row.name} --marketplace ${repo}`,
    complete: how.repo !== undefined,
    ...(snippet === undefined ? {} : { snippet }),
    notes,
  }
}

files.hooks/domain/discover.ts:
// Discover's logic: what a catalogue row says, the install
// review, the review that accepts a marketplace-declared command, and
// adding a marketplace. The catalogue itself lives in services/catalog.ts.

import type {
  CatalogPage,
  CatalogRow,
  Job,
  ReviewRequest,
  Scope,
  View,
} from '../../types/index.d.ts'
import { notableText } from './capabilities.ts'
import { SORTS } from './catalog.ts'
import { parseMarketplaceSource } from './ids.ts'

export const INSTALL_SCOPES = ['user', 'project', 'local'] as const
export type InstallScope = (typeof INSTALL_SCOPES)[number]

export const isInstallScope = (value: unknown): value is InstallScope =>
  typeof value === 'string' && (INSTALL_SCOPES as readonly string[]).includes(value)

/** What a scope means, for the review's Select. */
export const SCOPE_LABEL: Readonly<Record<InstallScope, string>> = {
  user: 'user: every project',
  project: 'project: this repository, shared',
  local: 'local: this repository, only you',
}

/** What modmgr could read about an entry before installing it (a local source's `validate`). */
export type Inspection = {
  readonly notable: readonly string[]
  readonly hasModule: boolean
}

/** A local entry modmgr tried to read and couldn't, and why. */
export type Unread = { readonly failed: string }

export const isUnread = (value: Inspection | Unread | undefined): value is Unread =>
  value !== undefined && 'failed' in value

/**
 * The review of installing `entry` (`i`): the scope (user by default), what it
 * can do when modmgr could read it, else that it couldn't (a remote source is
 * read only once installed).
 */
export const installReview = (
  entry: { readonly id: string; readonly name: string; readonly version?: string | undefined },
  scope: InstallScope,
  read: Inspection | Unread | undefined,
): ReviewRequest => {
  const inspection = isUnread(read) ? undefined : read
  const review: ReviewRequest = {
    action: 'install',
    targets: [
      {
        id: entry.id,
        op: 'install',
        scope,
        ...(entry.version === undefined ? {} : { version: entry.version }),
      },
    ],
    notable: (inspection?.notable ?? []).map(id => `${entry.name}: ${notableText(id)}`),
    changesRepoFile: scope !== 'user',
  }
  if (inspection !== undefined) return review
  return isUnread(read)
    ? { ...review, uninspected: true, unreadable: read.failed }
    : { ...review, uninspected: true }
}

/** The same review at another scope (the review's Select). */
export const withScope = (review: ReviewRequest, scope: Scope): ReviewRequest =>
  review.action !== 'install' || !isInstallScope(scope)
    ? review
    : {
        ...review,
        targets: review.targets.map(target => ({ ...target, scope })),
        changesRepoFile: scope !== 'user',
      }

/**
 * The review that accepts what a failed install or update was stopped by:
 * the command a marketplace declares (or the headers helper that fetches its
 * archive), verbatim, with its sha256. Confirming passes the sha with
 * `--accept-command`; the CLI runs it only if the command it would run still
 * has that sha, and otherwise shows the new one, which this review
 * shows again. Undefined for a job that wasn't stopped that way.
 */
export const acceptReview = (job: Job): ReviewRequest | undefined => {
  const { shown, target } = job
  if (shown === undefined || target === undefined) return undefined
  if (job.kind !== 'install' && job.kind !== 'update') return undefined
  const scope = job.args?.scope
  const declared = {
    text: shown.command,
    sha256: shown.sha256,
    ...(shown.truncated === true ? { truncated: true } : {}),
  }
  return {
    action: job.kind,
    targets: [{ id: target, op: job.kind, ...(scope === undefined ? {} : { scope }) }],
    notable: [],
    changesRepoFile: scope === 'project' || scope === 'local',
    ...(shown.kind === 'entry_helper'
      ? { headersHelper: declared }
      : { declaredCommand: declared }),
  }
}

/**
 * The newest failed job that waits for its declared command to be reviewed:
 * none once a later install or update of the same mod was queued or ran.
 */
export const awaitingAcceptance = (jobs: readonly Job[]): Job | undefined => {
  const at = jobs.findLastIndex(job => job.state === 'failed' && job.shown !== undefined)
  const stopped = jobs[at]
  if (stopped === undefined) return undefined
  const settled = jobs
    .slice(at + 1)
    .some(job => job.target === stopped.target && (job.kind === 'install' || job.kind === 'update'))
  return settled ? undefined : stopped
}

/**
 * The review of adding a marketplace (`m`), or why the source can't be one.
 * Adding fetches the catalogue (a clone for a repository) and writes your
 * settings; it runs no plugin code.
 */
export const marketplaceReview = (
  text: string,
): { readonly review: ReviewRequest } | { readonly error: string } => {
  const source = parseMarketplaceSource(text.trim())
  if (!source.ok) return { error: source.error.message }
  return {
    review: {
      action: 'marketplace',
      targets: [],
      notable: [],
      changesRepoFile: false,
      source: source.value,
    },
  }
}

/** The notable lines of an inspection, for the detail. */
export const inspectionLines = (inspection: Inspection): string[] =>
  inspection.notable.map(notableText)

/** The marketplace field's key. */
export const MARKETPLACE_KEY = 'marketplace-source'

/** A Discover row's Button key: what `ui.focus` and `ui.press` name. */
export const FOUND_PREFIX = 'found:'
export const foundKey = (id: string): string => `${FOUND_PREFIX}${id}`
export const foundOfKey = (key: string | undefined): string | undefined =>
  key?.startsWith(FOUND_PREFIX) === true ? key.slice(FOUND_PREFIX.length) : undefined

/** The catalogue row Discover shows as selected and acts on: the selection when drawn, else the first. */
export const foundRow = (view: View, page: CatalogPage): CatalogRow | undefined =>
  page.rows.find(row => row.id === view.found) ?? page.rows[0]

/** The next sort (`o`): installs → name → marketplace. */
export const nextSort = (sort: View['sort']): View['sort'] =>
  SORTS[(SORTS.indexOf(sort) + 1) % SORTS.length] ?? 'installs'

/**
 * `74 mods`, `74 mods among 1,804 of 3,544 checked`, or while it runs
 * `12 mods so far · checking 1,804 of 3,544`; undefined before it ran.
 */
export const detectLine = (detect: {
  readonly checked: number
  readonly total: number
  readonly found: number
  readonly running: boolean
}): string | undefined => {
  if (detect.total === 0) return undefined
  const n = (value: number) => value.toLocaleString('en-US')
  const mods = `${n(detect.found)} ${detect.found === 1 ? 'mod' : 'mods'}`
  if (detect.running)
    return detect.checked === 0
      ? `checking ${n(detect.total)} entries…`
      : `${mods} so far · checking ${n(detect.checked)} of ${n(detect.total)}`
  if (detect.checked >= detect.total) return mods
  return `${mods} among ${n(detect.checked)} of ${n(detect.total)} checked`
}

files.hooks/domain/health.ts:
// Health: what needs the person's attention, grouped by mod,
// each with a one-press fix where one exists, then modmgr's own state (the
// installed list's refresh, a reload owed, the detector, the cache, the update
// checks). Built from `$.state` alone, so it is drawn, never fetched.

import type {
  Attention,
  Degraded,
  DetectProgress,
  DevState,
  HealthFacts,
  JobQueue,
  ModRow,
  Sync,
} from '../../types/index.d.ts'
import { notableVerb } from './capabilities.ts'
import { isActive } from './jobs.ts'
import { sanitize } from './sanitize.ts'
import { bytesLabel, type Window, whyLocked, whyNoUpdate, windowAround } from './view.ts'

/** What pressing an item does. */
export type HealthFix =
  | { readonly kind: 'update' | 'open'; readonly id: string }
  | { readonly kind: 'validate'; readonly key: string }
  | { readonly kind: 'copy'; readonly text: string }
  | { readonly kind: 'reload' | 'refresh' | 'clear-cache' | 'check-updates' }

export type HealthTone = 'bad' | 'warn' | 'info'

export type HealthItem = {
  /** Stable: the Button's key. */
  readonly key: string
  /** The mod it concerns, or modmgr's own heading. */
  readonly group: string
  readonly tone: HealthTone
  readonly text: string
  readonly fix?: HealthFix
  /** What the fix does, in a word or two. */
  readonly fixLabel?: string
}

/** modmgr's own heading (apart from an installed mod named modmgr), and the hook-order notes'. */
export const OWN_GROUP = 'modmgr itself'
export const ORDER_GROUP = 'Hook order'

/** A Health item's Button key: what `ui.focus` and `ui.press` name. */
export const HEALTH_PREFIX = 'health:'
export const healthKey = (key: string): string => `${HEALTH_PREFIX}${key}`
export const healthOfKey = (key: string | undefined): string | undefined =>
  key?.startsWith(HEALTH_PREFIX) === true ? key.slice(HEALTH_PREFIX.length) : undefined

const plural = (n: number, one: string, many: string): string => `${n} ${n === 1 ? one : many}`

/** `just now`, `5 min ago`, `3 h ago`, `2 days ago`. */
export const agoLabel = (ms: number): string => {
  const minutes = Math.floor(Math.max(0, ms) / 60_000)
  if (minutes < 1) return 'just now'
  if (minutes < 60) return `${minutes} min ago`
  const hours = Math.floor(minutes / 60)
  if (hours < 48) return `${hours} h ago`
  return `${Math.floor(hours / 24)} days ago`
}

export type HealthInput = {
  readonly mods: readonly ModRow[]
  readonly dev: DevState
  readonly attention: Attention
  readonly degraded: Degraded
  readonly sync: Sync
  readonly detect: DetectProgress
  readonly queue: JobQueue
  readonly facts: HealthFacts
}

const TONE_ORDER: Readonly<Record<HealthTone, number>> = { bad: 0, warn: 1, info: 2 }

/** Each mod's items: what is wrong first. */
const modItems = (input: HealthInput): HealthItem[] => {
  const items: HealthItem[] = []
  const devKeyOf = new Map(input.dev.rows.map(row => [row.name, row.key]))
  for (const row of input.mods) {
    const group = sanitize(row.name, { max: 40 })
    if (row.problems > 0) {
      items.push({
        key: `${row.id}:validate`,
        group,
        tone: 'bad',
        text: `validate finds ${plural(row.problems, 'error', 'errors')} in it`,
        fix: { kind: 'open', id: row.id },
        fixLabel: 'see it',
      })
    }
    if (row.capsNew !== undefined) {
      const added = row.capsNew.added.map(notableVerb).join(', ')
      items.push({
        key: `${row.id}:caps`,
        group,
        tone: 'warn',
        text: `since ${sanitize(row.capsNew.since, { max: 20 })} it can ${added}`,
        fix: { kind: 'open', id: row.id },
        fixLabel: 'review it',
      })
    }
    if (row.updateTo !== undefined && whyNoUpdate(row) === undefined) {
      items.push({
        key: `${row.id}:update`,
        group,
        tone: 'info',
        text: `${sanitize(row.updateTo, { max: 20 })} is available`,
        fix: { kind: 'update', id: row.id },
        fixLabel: 'update',
      })
    }
  }
  // Failures the session reported while hot-reloading (Dev's), and the debug log's.
  const names = new Set([...Object.keys(input.dev.failures), ...Object.keys(input.facts.logged)])
  for (const name of [...names].sort()) {
    const group = sanitize(name, { max: 40 })
    const failed = input.dev.failures[name]
    const devKey = devKeyOf.get(name)
    if (failed !== undefined) {
      items.push({
        key: `${name}:failures`,
        group,
        tone: 'bad',
        text: `${plural(failed.count, 'failure', 'failures')} while it reloaded; last: ${failed.lastReason}`,
        ...(devKey === undefined
          ? {}
          : { fix: { kind: 'validate' as const, key: devKey }, fixLabel: 'validate' }),
      })
    }
    const logged = input.facts.logged[name]
    if (logged !== undefined) {
      items.push({
        key: `${name}:logged`,
        group,
        tone: 'bad',
        text: `a hook failed: ${sanitize(logged, { max: 160 })} (debug log)`,
      })
    }
  }
  // By mod, worst first; the mods in Installed's order, then the rest by name.
  const order = [...input.mods.map(row => sanitize(row.name, { max: 40 }))]
  const rank = (group: string) => {
    const at = order.indexOf(group)
    return at < 0 ? order.length : at
  }
  const worst = new Map<string, number>()
  for (const item of items) {
    worst.set(item.group, Math.min(worst.get(item.group) ?? 9, TONE_ORDER[item.tone]))
  }
  return items.sort(
    (a, b) =>
      (worst.get(a.group) ?? 9) - (worst.get(b.group) ?? 9) ||
      rank(a.group) - rank(b.group) ||
      a.group.localeCompare(b.group) ||
      TONE_ORDER[a.tone] - TONE_ORDER[b.tone],
  )
}

/** modmgr's own state, and the load states in one line. */
const ownItems = (input: HealthInput): HealthItem[] => {
  const { attention, degraded, sync, detect, facts, queue } = input
  const items: HealthItem[] = []
  const own = (item: Omit<HealthItem, 'group'>) => items.push({ ...item, group: OWN_GROUP })
  if (degraded.process) {
    own({ key: 'own:process', tone: 'bad', text: sanitize(degraded.reason ?? '', { max: 300 }) })
  }
  if (sync.error !== undefined) {
    own({
      key: 'own:sync',
      tone: 'bad',
      text: `couldn't read the installed list: ${sanitize(sync.error.message, { max: 160 })}`,
      fix: { kind: 'refresh' },
      fixLabel: 'try again',
    })
  }
  const reloadQueued = queue.jobs.some(job => job.kind === 'reload' && isActive(job))
  if (attention.reloadPending && !reloadQueued) {
    own({
      key: 'own:reload',
      tone: 'warn',
      text: 'changes wait for a plugin reload',
      fix: { kind: 'reload' },
      fixLabel: 'reload',
    })
  }
  if (facts.cache.full) {
    own({
      key: 'own:cache',
      tone: 'bad',
      text: "modmgr's cache is full; what it knows is not saved",
      fix: { kind: 'clear-cache' },
      fixLabel: 'clear cache',
    })
  }
  if (degraded.acceptCommand) {
    own({
      key: 'own:accept',
      tone: 'info',
      text: 'Claude Code refuses declared-command acceptances from this session; accept them in a terminal',
    })
  }
  const counts = loadStates(input.mods)
  if (counts !== undefined) own({ key: 'own:load', tone: 'info', text: counts })
  const updates = facts.updates
  // Said once the facts are in (the first frame has none, and would say "every 0 hours").
  if (facts.at !== undefined)
    own({
      key: 'own:updates',
      tone: 'info',
      text:
        updates.off !== undefined
          ? `update checks are off: ${updates.off}`
          : `updates checked ${updates.at === undefined || facts.at === undefined ? 'never' : agoLabel(facts.at - updates.at)}, every ${plural(updates.every, 'hour', 'hours')}`,
      ...(updates.off === undefined
        ? { fix: { kind: 'check-updates' as const }, fixLabel: 'check now' }
        : {}),
    })
  const left = Math.max(0, facts.detector.budget - facts.detector.spent)
  // Where Discover's kinds came from: the catalogue index (and how old it is), then checks here.
  const index =
    detect.indexAt === undefined || facts.at === undefined
      ? ''
      : `, from the catalogue index built ${agoLabel(facts.at - detect.indexAt)}`
  own({
    key: 'own:detector',
    tone: 'info',
    text:
      detect.total === 0
        ? 'detector: not run yet; it starts when Discover opens'
        : facts.detector.remote
          ? `detector: ${detect.found} mods found${index}; ${detect.checked.toLocaleString('en-US')} of ${detect.total.toLocaleString('en-US')} checked, ${left} requests left this session`
          : `detector: local catalogues only (${facts.detector.why ?? 'remote checks are off'}); ${detect.found} mods found`,
  })
  if (!facts.cache.full) {
    own({
      key: 'own:cache',
      tone: 'info',
      text: `cache: ${bytesLabel(facts.cache.bytes)}`,
      fix: { kind: 'clear-cache' },
      fixLabel: 'clear',
    })
  }
  const log = facts.debugLog
  if (log.state === 'too-big' && log.path !== undefined) {
    own({
      key: 'own:debug',
      tone: 'warn',
      text: "this session's debug log is too large to read here (over 4 MiB)",
      fix: { kind: 'copy', text: `grep 'hook failed closed' ${log.path}` },
      fixLabel: 'copy a search',
    })
  }
  if (log.state === 'none') {
    own({
      key: 'own:debug',
      tone: 'info',
      text: 'A hook that fails is logged only in a session started with --debug',
      fix: { kind: 'copy', text: 'claude --debug' },
      fixLabel: 'copy command',
    })
  }
  return items
}

/** `4 enabled · 1 disabled · 1 managed · 2 from the launch command`, or nothing with no mods. */
export const loadStates = (mods: readonly ModRow[]): string | undefined => {
  if (mods.length === 0) return undefined
  const managed = mods.filter(row => row.scope === 'managed').length
  const launched = mods.filter(
    row => row.origin === 'env-dir' || row.origin === 'plugin-dir',
  ).length
  const other = mods.filter(row => whyLocked(row) === undefined)
  const enabled = other.filter(row => row.enabled).length
  const disabled = other.length - enabled
  return [
    `${enabled} enabled`,
    disabled === 0 ? '' : `${disabled} disabled`,
    managed === 0 ? '' : `${managed} managed`,
    launched === 0 ? '' : `${launched} from the launch command`,
  ]
    .filter(part => part !== '')
    .join(' · ')
}

/** Every item Health draws: the mods', the hook-order notes, then modmgr's own. */
export const healthItemsOf = (input: HealthInput): HealthItem[] => [
  ...modItems(input),
  ...input.facts.chain.map(
    (note): HealthItem => ({
      key: `order:${note.event}`,
      group: ORDER_GROUP,
      tone: 'info',
      text: sanitize(note.text, { max: 300 }),
    }),
  ),
  ...ownItems(input),
]

/** How many items say something is wrong (the tab's `▲n`). */
export const problemCount = (items: readonly HealthItem[]): number =>
  items.filter(item => item.tone === 'bad').length

/**
 * The last `hook failed closed: <plugin>: errorKind=… (<event>; …)` line per
 * plugin in a debug log (the engine logs the error's length, not its text).
 */
export const loggedFailures = (log: string): Record<string, string> => {
  const found: Record<string, string> = {}
  const line =
    /hook failed closed: ([a-z0-9][a-z0-9._-]{0,63})(?:@[a-z0-9._-]+)?: errorKind=(\w+)[^(]*\(([\w.]+)/g
  for (const match of log.matchAll(line)) {
    const [, name, kind, event] = match
    if (name !== undefined && kind !== undefined && event !== undefined) {
      found[name] = `${event} (${kind})`
    }
  }
  return found
}

/** A row of Health's list: a group's name, or one of its items. */
export type HealthLine =
  | { readonly kind: 'group'; readonly group: string }
  | { readonly kind: 'item'; readonly item: HealthItem }

/**
 * The rows of Health's list that fit in `rows` around `items[at]`: each
 * group's name on a row of its own above its items, again at the top when the
 * window starts inside a group. `items` is the window over the items, for
 * the pager.
 */
export const healthLines = (
  items: readonly HealthItem[],
  at: number,
  rows: number,
): { readonly lines: HealthLine[]; readonly items: Window } => {
  const all: HealthLine[] = []
  items.forEach((item, index) => {
    if (index === 0 || items[index - 1]?.group !== item.group)
      all.push({ kind: 'group', group: item.group })
    all.push({ kind: 'item', item })
  })
  const size = Math.max(2, rows)
  const selected = items[at]
  const focus = all.findIndex(line => line.kind === 'item' && line.item === selected)
  const window = windowAround(all.length, focus, size)
  let lines = all.slice(window.start, window.end)
  const first = lines[0]
  if (first?.kind === 'item') {
    lines = [{ kind: 'group', group: first.item.group }, ...lines]
    // Over by the name: cut the end, or the top item when that would take the
    // selection or the row under it (the arrows' way down).
    const near = lines.slice(-2).some(line => line.kind === 'item' && line.item === selected)
    if (near && lines[1] !== undefined && !(lines[1].kind === 'item' && lines[1].item === selected))
      lines.splice(1, 1)
    else lines.pop()
    // A top item cut away leaves the next group's name right under this one.
    if (lines[1]?.kind === 'group') lines.shift()
  }
  // A group's name with none of its items under it.
  if (lines.at(-1)?.kind === 'group') lines.pop()
  const shown = lines.flatMap(line => (line.kind === 'item' ? [items.indexOf(line.item)] : []))
  return {
    lines,
    items: { start: shown[0] ?? 0, end: (shown.at(-1) ?? -1) + 1 },
  }
}

files.hooks/domain/view.ts:
// The pane's logic as pure functions: which rows show, the staged
// toggles and the review they become, the Esc cascade, the band's line and
// the status line. services/actions.ts applies them to `$.state`; ui/ draws
// what they return.

import type {
  Attention,
  Job,
  JobQueue,
  ModRow,
  Overlay,
  ReviewOp,
  ReviewRequest,
  ReviewTarget,
  Scope,
  View,
} from '../../types/index.d.ts'
import { argvOf, commandOfJob } from './argv.ts'
import { notableText } from './capabilities.ts'
import { capsLine } from './caps-history.ts'
import { isActive, type JobSpec, NEEDS_RELOAD, type UndoStep } from './jobs.ts'
import { sanitize } from './sanitize.ts'

/** The name part of a plugin id (`turn-band` of `turn-band@fixtures`). */
export const nameOf = (id: string): string => {
  const at = id.indexOf('@')
  return at < 0 ? id : id.slice(0, at)
}

/** The one pane modmgr opens. */
export const PANE_ID = 'modmgr'
export const PANE_TITLE = 'mods'

/** From this many body columns the list and the detail sit side by side. */
export const SPLIT_MIN_COLUMNS = 80

export type Layout = 'stacked' | 'split'

/** The filter field's key. */
export const FILTER_KEY = 'filter'

/** A row's Button key: what `ui.focus` and `ui.press` name. */
export const ROW_PREFIX = 'row:'
export const rowKey = (id: string): string => `${ROW_PREFIX}${id}`
/** The mod id a focused element names, when it is a row. */
export const rowOfKey = (key: string | undefined): string | undefined =>
  key?.startsWith(ROW_PREFIX) === true ? key.slice(ROW_PREFIX.length) : undefined

export const layoutFor = (bodyColumns: number): Layout =>
  bodyColumns >= SPLIT_MIN_COLUMNS ? 'split' : 'stacked'

/** The list's columns beside the detail: about two fifths, never cramped or sprawling. */
export const listColumnsFor = (bodyColumns: number): number =>
  Math.max(28, Math.min(46, Math.floor(bodyColumns * 0.4)))

/** How a dialog open asks: `holdToasts` only while nothing streams. */
export type PaneOpen = {
  readonly id: string
  readonly title: string
  readonly closeOnEscape: true
  readonly focus?: true
  readonly holdToasts?: true
  readonly rows?: number
  readonly columns?: number
}

/**
 * Rows a dialog asks for inline: the list plus its chrome, at least 14 (a
 * detail or a review is taller than a short list), never more than 24.
 */
export const rowsFor = (mods: number): number => Math.min(24, Math.max(14, mods + 6))

/** Columns a docked dialog asks for: room for the list and the detail side by side. */
export const DOCK_COLUMNS = 96

export const paneOpen = (how: {
  readonly focus: boolean
  readonly hold: boolean
  readonly mods: number
  readonly title?: string
}): PaneOpen => ({
  id: PANE_ID,
  title: how.title ?? PANE_TITLE,
  closeOnEscape: true,
  rows: rowsFor(how.mods),
  columns: DOCK_COLUMNS,
  ...(how.focus ? { focus: true as const } : {}),
  ...(how.hold ? { holdToasts: true as const } : {}),
})

/**
 * Whether an open of the dialog holds other plugins' toasts: only while
 * nothing runs or waits and the job log isn't on top, since a pane that stays
 * open must not silence them for long.
 */
export const holdsToasts = (queue: JobQueue, view: View): boolean =>
  !queue.jobs.some(isActive) && view.stack.at(-1) !== 'jobs'

// ---- rows -------------------------------------------------------------------

/** Installed rows matching the filter: by name or id, case-insensitive. */
export const filterRows = (rows: readonly ModRow[], query: string): ModRow[] => {
  const needle = query.trim().toLowerCase()
  if (needle === '') return [...rows]
  return rows.filter(
    row => row.name.toLowerCase().includes(needle) || row.id.toLowerCase().includes(needle),
  )
}

/** The rows `[start, end)` a window of `size` shows. */
export type Window = { readonly start: number; readonly end: number }

/**
 * A window of `size` rows over `count`, centred on `index` where the list
 * allows, so the rows on either side of the focused one are always drawn and
 * the arrows walk onto them (the ring moves only between drawn elements).
 */
export const windowAround = (count: number, index: number, size: number): Window => {
  const rows = Math.max(1, Math.floor(size))
  if (count <= rows) return { start: 0, end: Math.max(0, count) }
  const at = Math.min(Math.max(0, index), count - 1)
  const start = Math.min(Math.max(0, at - Math.floor((rows - 1) / 2)), count - rows)
  return { start, end: start + rows }
}

/** `6–15 of 40`, or undefined when every row shows. */
export const pagerLabel = (window: Window, count: number): string | undefined =>
  window.start === 0 && window.end >= count
    ? undefined
    : `${(window.start + 1).toLocaleString('en-US')}–${window.end.toLocaleString('en-US')} of ${count.toLocaleString('en-US')}`

/** The row the selection moves to when `id` goes: the next one shown, else the one before. */
export const neighbourOf = (
  view: View,
  mods: readonly ModRow[],
  id: string,
): ModRow | undefined => {
  const rows = filterRows(mods, view.query)
  const at = rows.findIndex(row => row.id === id)
  if (at < 0) return undefined
  return rows[at + 1] ?? rows[at - 1]
}

/** The selected row's index among `rows`, 0 when it isn't there. */
export const selectedIndex = (rows: readonly ModRow[], selected: string | undefined): number => {
  const index = rows.findIndex(row => row.id === selected)
  return index < 0 ? 0 : index
}

/**
 * The row the pane shows as selected and every action acts on: the selection
 * when the filter shows it, else the first row shown.
 * One resolver, so the drawing and a press never disagree.
 */
export const selectedRow = (view: View, mods: readonly ModRow[]): ModRow | undefined => {
  const rows = filterRows(mods, view.query)
  return rows.find(row => row.id === view.selected) ?? rows[0]
}

// ---- staging ----------------------------------------------------------------

/**
 * Stages a toggle of `row`: flips what it will be after apply. Staging it
 * back to its current state un-stages it. A row the CLI can't toggle is
 * left alone.
 */
export const stageToggle = (view: View, row: ModRow): View => {
  if (!row.toggleable) return view
  const { [row.id]: current, ...rest } = view.staged
  const target = !(current ?? row.enabled)
  return { ...view, staged: target === row.enabled ? rest : { ...rest, [row.id]: target } }
}

export type Change = { readonly row: ModRow; readonly enable: boolean }

/** The staged toggles that still change something, in row order. */
export const stagedChanges = (view: View, rows: readonly ModRow[]): Change[] =>
  rows.flatMap(row => {
    const enable = view.staged[row.id]
    return enable === undefined || enable === row.enabled || !row.toggleable
      ? []
      : [{ row, enable }]
  })

/** The ids whose staged entry still changes something: what rows and the detail mark as staged. */
export const stagedIds = (view: View, rows: readonly ModRow[]): ReadonlySet<string> =>
  new Set(stagedChanges(view, rows).map(change => change.row.id))

/** Drops staged entries that no longer change anything (a refresh moved under them). */
export const pruneStaged = (view: View, rows: readonly ModRow[]): View => {
  const kept = Object.fromEntries(stagedChanges(view, rows).map(c => [c.row.id, c.enable]))
  return Object.keys(kept).length === Object.keys(view.staged).length
    ? view
    : { ...view, staged: kept }
}

/** Why a row can't be toggled from here, in the person's terms; undefined when it can. */
export const whyLocked = (row: ModRow): string | undefined => {
  if (row.toggleable) return undefined
  if (row.scope === 'managed') return "managed by your organisation; it can't be turned off here"
  if (row.origin === 'env-dir')
    return 'loaded from CLAUDE_CODE_PLUGIN_DIRS; take it out of that variable and restart to stop loading it'
  if (row.origin === 'plugin-dir')
    return 'loaded with --plugin-dir; leave the flag out of your launch command to stop loading it'
  return "this session loaded it from its launch command; it can't be toggled here"
}

const cliScope = (scope: Scope | undefined): 'user' | 'project' | 'local' | undefined =>
  scope === 'user' || scope === 'project' || scope === 'local' ? scope : undefined

/** Why the CLI can't update a row, in the person's terms; undefined when it can. */
export const whyNoUpdate = (row: ModRow): string | undefined => {
  if (row.scope === 'managed') return 'managed by your organisation; it updates with their settings'
  if (row.origin === 'folder-marketplace') return 'runs from its marketplace folder: no updates'
  if (row.origin === 'skills-dir')
    return 'lives in your skills folder; it changes when its files do'
  return whyLocked(row)
}

/** Why the CLI can't remove a row; undefined when it can. */
export const whyNoRemove = (row: ModRow): string | undefined => {
  if (row.scope === 'managed') return "managed by your organisation; it can't be removed here"
  if (row.origin === 'skills-dir') return 'lives in your skills folder; delete its folder there'
  return whyLocked(row)
}

/** What a review needs to know about one mod beyond its row. */
export type ReviewFacts = {
  readonly notable: readonly string[]
  readonly parts?: { readonly skills: number; readonly agents: number; readonly mcp: number }
  /** Its data folder's size, when it has one. */
  readonly dataBytes?: number
}

type Parts = { skills: number; agents: number; mcp: number }

const addParts = (into: Parts, parts: ReviewFacts['parts']): void => {
  if (parts === undefined) return
  into.skills += parts.skills
  into.agents += parts.agents
  into.mcp += parts.mcp
}

const withParts = (review: ReviewRequest, parts: Parts): ReviewRequest =>
  parts.skills + parts.agents + parts.mcp > 0 ? { ...review, parts } : review

const targetOf = (row: ModRow, op: ReviewOp): ReviewTarget => {
  const scope = cliScope(row.scope)
  return {
    id: row.id,
    op,
    ...(scope === undefined ? {} : { scope }),
    ...(row.version === undefined ? {} : { version: row.version }),
  }
}

const touchesRepo = (scope: Scope | undefined): boolean => scope === 'project' || scope === 'local'

/** The review a batch of toggles opens: one confirm for the whole batch. */
export const toggleReview = (
  changes: readonly Change[],
  facts: (id: string) => ReviewFacts | undefined,
): ReviewRequest => {
  const notable: string[] = []
  const parts = { skills: 0, agents: 0, mcp: 0 }
  for (const { row, enable } of changes) {
    const known = facts(row.id)
    if (enable) {
      for (const id of known?.notable ?? []) notable.push(`${row.name}: ${notableText(id)}`)
    } else {
      addParts(parts, known?.parts)
    }
  }
  return withParts(
    {
      action: 'toggle',
      targets: changes.map(({ row, enable }) => targetOf(row, enable ? 'enable' : 'disable')),
      notable,
      changesRepoFile: changes.some(({ row }) => touchesRepo(row.scope)),
    },
    parts,
  )
}

/** The marketplace a plugin id names. */
export const marketplaceOf = (id: string): string => id.slice(id.indexOf('@') + 1)

/**
 * The review of updating `rows` (`u` one, `a` all): each marketplace is
 * refreshed first, then each mod updated, then one reload. It runs new code,
 * so it is always reviewed; it can't be undone.
 */
export const updateReview = (rows: readonly ModRow[]): ReviewRequest => {
  const marketplaces = [...new Set(rows.map(row => marketplaceOf(row.id)))].sort()
  return {
    action: 'update',
    targets: rows.map(row => targetOf(row, 'update')),
    notable: [],
    changesRepoFile: false,
    marketplaces,
  }
}

/**
 * The review of removing `row` (`x`): what goes, from which scope, its other
 * parts and its data, which is kept unless the person asks otherwise.
 */
export const removeReview = (row: ModRow, facts: ReviewFacts | undefined): ReviewRequest => {
  const parts = { skills: 0, agents: 0, mcp: 0 }
  addParts(parts, facts?.parts)
  const review: ReviewRequest = {
    action: 'remove',
    targets: [targetOf(row, 'remove')],
    notable: [],
    changesRepoFile: touchesRepo(row.scope),
    keepData: true,
  }
  return withParts(
    facts?.dataBytes === undefined ? review : { ...review, dataBytes: facts.dataBytes },
    parts,
  )
}

const UNDO_OP: Readonly<Partial<Record<JobSpec['kind'], ReviewOp>>> = {
  enable: 'enable',
  disable: 'disable',
  install: 'install',
  remove: 'remove',
}

/**
 * The review of an undo that reinstalls (the inverse of a remove): what comes
 * back, what it can do, and that a declared install command stops it.
 */
export const undoReview = (
  plan: { readonly batch: string; readonly steps: readonly UndoStep[] },
  rows: readonly ModRow[],
  facts: (id: string) => ReviewFacts | undefined,
): ReviewRequest => {
  const { steps } = plan
  const notable: string[] = []
  const parts = { skills: 0, agents: 0, mcp: 0 }
  const targets = steps.flatMap(({ spec, undoes }): ReviewTarget[] => {
    const op = UNDO_OP[spec.kind]
    if (op === undefined || spec.target === undefined) return []
    // A queue job's target is checked only when it runs: drawn, it is sanitised.
    const name = sanitize(rows.find(row => row.id === spec.target)?.name ?? nameOf(spec.target), {
      max: 40,
    })
    const known = facts(spec.target)
    if (op === 'install' || op === 'enable') {
      for (const id of known?.notable ?? []) notable.push(`${name}: ${notableText(id)}`)
    } else {
      addParts(parts, known?.parts)
    }
    const scope = cliScope(spec.args?.scope)
    return [
      {
        id: spec.target,
        op,
        ...(scope === undefined ? {} : { scope }),
        // What the CLI said it did with the data, not what modmgr asked.
        ...(op === 'install' && undoes.keptData !== undefined ? { keptData: undoes.keptData } : {}),
      },
    ]
  })
  return withParts(
    {
      action: 'undo',
      targets,
      notable,
      changesRepoFile: targets.some(target => touchesRepo(target.scope)),
      undoes: plan.batch,
    },
    parts,
  )
}

/** The jobs a confirmed review queues (the batch's reload is added by `enqueue`). */
export const specsOf = (review: ReviewRequest): JobSpec[] => {
  if (review.action === 'marketplace') {
    return review.source === undefined
      ? []
      : [{ kind: 'marketplace-add', args: { source: review.source } }]
  }
  const refresh: JobSpec[] = (review.marketplaces ?? []).map(name => ({
    kind: 'marketplace-update',
    target: name,
  }))
  // The sha of the command shown: the CLI runs it only while it still matches.
  const accepted = (review.declaredCommand ?? review.headersHelper)?.sha256
  const ops = review.targets.map((target): JobSpec => {
    const scope = cliScope(target.scope)
    const scoped = scope === undefined ? {} : { scope }
    const kind = target.op
    const args: Job['args'] =
      kind === 'remove'
        ? { ...scoped, keepData: review.keepData !== false }
        : (kind === 'install' || kind === 'update') && accepted !== undefined
          ? { ...scoped, acceptSha: accepted }
          : scoped
    return Object.keys(args).length === 0
      ? { kind, target: target.id }
      : { kind, target: target.id, args }
  })
  return [...refresh, ...ops]
}

/** The CLI line a job runs, for the review's "Runs" lines; undefined when it can't be built. */
export const commandLine = (spec: JobSpec): string | undefined => {
  const job: Job = { id: 'review', kind: spec.kind, state: 'queued', tail: [] }
  const command = commandOfJob({
    ...job,
    ...(spec.target === undefined ? {} : { target: spec.target }),
    ...(spec.args === undefined ? {} : { args: spec.args }),
  })
  return command.ok ? argvOf(command.value).join(' ') : undefined
}

/** `2 skills, 1 MCP server`; empty when there is nothing. */
export const partsLabel = (parts: {
  readonly skills: number
  readonly agents: number
  readonly mcp: number
}): string => {
  const say = (n: number, one: string, many: string) =>
    n === 0 ? [] : [`${n} ${n === 1 ? one : many}`]
  return [
    ...say(parts.skills, 'skill', 'skills'),
    ...say(parts.agents, 'agent', 'agents'),
    ...say(parts.mcp, 'MCP server', 'MCP servers'),
  ].join(', ')
}

/** `12 KB`: a data folder's size, rounded. */
export const bytesLabel = (n: number): string =>
  n < 1024
    ? `${n} B`
    : n < 1024 * 1024
      ? `${Math.round(n / 1024)} KB`
      : `${(n / 1048576).toFixed(1)} MB`

/**
 * Rows `texts` wrap to at `columns`, each at least one (a wrapped Text's
 * height): words move whole to the next row, as the terminal wraps them, and
 * a word longer than the row is cut across rows.
 */
export const wrappedRows = (texts: readonly string[], columns: number): number => {
  const width = Math.max(1, columns)
  const rowsOf = (text: string): number => {
    let rows = 1
    let used = 0
    for (const word of text.split(' ')) {
      const length = [...word].length
      const need = used === 0 ? length : used + 1 + length
      if (need <= width) {
        used = need
        continue
      }
      if (used > 0) rows += 1
      rows += Math.max(0, Math.ceil(length / width) - 1)
      used = length % width === 0 && length > 0 ? width : length % width
    }
    return rows
  }
  return texts.reduce((sum, text) => sum + rowsOf(text), 0)
}

/**
 * Rows a wrapping row of items takes at `columns` (the footer's keys, laid
 * out with `columnGap`): each line fills until the next item would overflow.
 */
export const footerRowsFor = (widths: readonly number[], columns: number, gap = 2): number => {
  const line = Math.max(1, columns)
  let rows = 1
  let used = 0
  for (const width of widths) {
    const need = used === 0 ? width : used + gap + width
    if (used > 0 && need > line) {
      rows += 1
      used = width
    } else {
      used = need
    }
    // An item wider than the line wraps inside itself; the next starts on a new line.
    if (used > line) {
      rows += Math.ceil(used / line) - 1
      used = line
    }
  }
  return rows
}

// ---- overlays and Esc -------------------------------------------------------

export const topOverlay = (view: View): Overlay | undefined => view.stack.at(-1)

/** Pushes an overlay; one already on the stack moves to the top instead of repeating. */
export const pushOverlay = (view: View, overlay: Overlay): View => ({
  ...view,
  stack: [...view.stack.filter(item => item !== overlay), overlay],
})

export const popOverlay = (view: View): View =>
  view.stack.length === 0 ? view : { ...view, stack: view.stack.slice(0, -1) }

/** Opens an overlay, or closes it when it is already on top (the `h` and `j` keys). */
export const toggleOverlay = (view: View, overlay: Overlay): View =>
  topOverlay(view) === overlay ? popOverlay(view) : pushOverlay(view, overlay)

export type Escape =
  | { readonly kind: 'pop'; readonly view: View }
  | { readonly kind: 'to-list' }
  | { readonly kind: 'clear-query'; readonly view: View }
  | { readonly kind: 'close' }

/**
 * What an Esc does: while the pane holds the keys it
 * pops the top overlay, then brings the ring back to the list from a key
 * (`ringAway`: beside the list, in the footer), then clears the filter, then
 * closes. An Esc at the prompt (the pane not focused) always closes: the
 * person can't see what a cascade would pop.
 */
export const escapeStep = (view: View, paneFocused: boolean, ringAway = false): Escape => {
  if (!paneFocused) return { kind: 'close' }
  if (view.stack.length > 0) return { kind: 'pop', view: popOverlay(view) }
  if (ringAway) return { kind: 'to-list' }
  // The field of the tab shown: Installed's filter, or Discover's search.
  if (view.tab === 'discover' && view.search !== '')
    return { kind: 'clear-query', view: { ...view, search: '' } }
  if (view.tab === 'installed' && view.query !== '')
    return { kind: 'clear-query', view: { ...view, query: '' } }
  return { kind: 'close' }
}

/** The view a closed pane leaves: no overlays, no review half-done; staged toggles stay. */
export const closedView = (view: View): View => {
  const { notice: _notice, ...rest } = view
  return { ...rest, stack: [] }
}

// ---- jobs: the batch line, the band, the status line and the title ------------

const describeJob = (job: Job): string => {
  const what =
    job.kind === 'reload'
      ? 'reload plugins'
      : job.kind === 'marketplace-update'
        ? 'refresh marketplace'
        : job.kind
  return job.target === undefined ? what : `${what} ${sanitize(job.target, { max: 60 })}`
}

/** The jobs of the newest batch, oldest first. */
export const latestBatch = (jobs: readonly Job[]): Job[] => {
  const batch = jobs.findLast(job => job.batch !== undefined)?.batch
  return batch === undefined ? [] : jobs.filter(job => job.batch === batch)
}

export type Status = {
  readonly tone: 'busy' | 'ok' | 'error'
  readonly text: string
}

const plural = (n: number, one: string, many: string): string => `${n} ${n === 1 ? one : many}`

/** How a finished batch's work reads: what changed, and what was already so. */
export const doneText = (work: readonly Job[]): string => {
  const changed = work.filter(job => job.state === 'ok' && job.unchanged !== true)
  const same = work.length - changed.length
  const updates = work.every(job => job.kind === 'update')
  if (updates) {
    if (changed.length === 0) return same === 1 ? 'already up to date' : 'all already up to date'
    return same === 0
      ? `${changed.length} updated`
      : `${changed.length} updated, ${same} already up to date`
  }
  if (changed.length === 0) return 'nothing needed changing'
  const [only] = changed
  if (changed.length === 1 && same === 0 && only?.target !== undefined) {
    const name = sanitize(nameOf(only.target), { max: 40 })
    if (only.kind === 'remove') return `${name} removed`
    if (only.kind === 'install') return `${name} installed`
  }
  const applied = plural(changed.length, 'change', 'changes')
  return same === 0 ? `${applied} applied` : `${applied} applied, ${same} already so`
}

/**
 * The jobs a batch counts as its work: not the reload, and not a marketplace
 * refresh (a step of an update). The pane's batch line and the summary share
 * it, so they count a batch alike.
 */
export const isWork = (job: Job): boolean =>
  job.kind !== 'reload' && job.kind !== 'marketplace-update'

/**
 * One line about the newest batch, in the pane: what runs now, or how it
 * ended. A failure stays until the next batch; a success shows only while
 * `showDone` (the band's echo, which the runner clears after a while: that
 * write is what redraws the pane). A batch that changed
 * nothing gets the same echo, though its reload never ran.
 */
export const batchLineOf = (queue: JobQueue, showDone: boolean): Status | undefined => {
  const jobs = latestBatch(queue.jobs)
  if (jobs.length === 0) return undefined
  const running = jobs.find(job => job.state === 'running')
  const work = jobs.filter(isWork)
  const done = work.filter(job => job.state !== 'queued' && job.state !== 'running').length
  if (running !== undefined) {
    if (running.kind === 'reload') return { tone: 'busy', text: 'reloading plugins…' }
    if (running.kind === 'marketplace-update')
      return { tone: 'busy', text: `${describeJob(running)}…` }
    return { tone: 'busy', text: `${describeJob(running)} (${done + 1} of ${work.length})…` }
  }
  if (jobs.some(job => job.state === 'queued')) {
    return work.every(job => job.state !== 'queued')
      ? { tone: 'busy', text: 'reload waits for the settings to settle…' }
      : { tone: 'busy', text: `${plural(work.length, 'change', 'changes')} queued…` }
  }
  const failed = jobs.filter(job => job.state === 'failed' || job.state === 'interrupted')
  if (failed.length > 0) {
    const first = failed[0]
    const why = first?.error?.message === undefined ? '' : `: ${first.error.message}`
    return {
      tone: 'error',
      text: `${failed.length} of ${jobs.length} failed (${describeJob(first as Job)}${why})`,
    }
  }
  if (!showDone) return undefined
  const reload = jobs.find(job => job.kind === 'reload')
  if (work.length === 0) return { tone: 'ok', text: 'plugins reloaded' }
  const text = doneText(work)
  return { tone: 'ok', text: reload?.state === 'ok' ? `${text}, plugins reloaded` : text }
}

/**
 * What modmgr has to say outside the dialog, in one value: the band,
 * the status line and the pane title are each drawn from it, so they never
 * disagree.
 */
export type Summary = {
  /** The job running now, not the reload (a refresh, a change, a test). */
  readonly running?: Job
  /** Changes (jobs that need a reload) queued or running: what "applying" counts. */
  readonly pending: number
  /** The batch's reload is running (or waiting for the turn to end). */
  readonly reloading: boolean
  /** A reload is owed and none is queued: `[l reload]`. */
  readonly reloadOwed: boolean
  readonly updates: number
  /** Mods whose update added notable capabilities not yet seen. */
  readonly capsCount: number
  /** "turn-band can now run programs", when something is new. */
  readonly caps?: string
  /**
   * The person dismissed the band line that said this news (updates, what an
   * update added): the status line and the title leave it out too, until it
   * changes. What is under way or owed is never quieted.
   */
  readonly newsDismissed: boolean
  /** The CLI's answer to the last reload, or how a batch that needed none ended. */
  readonly echo?: string
}

const updatesText = (n: number): string | undefined =>
  n > 0 ? plural(n, 'update', 'updates') : undefined

export const summaryOf = (input: {
  readonly attention: Attention
  readonly queue: JobQueue
  readonly mods: readonly ModRow[]
}): Summary => {
  const { attention, queue, mods } = input
  const reloadJob = queue.jobs.find(job => job.kind === 'reload' && isActive(job))
  const running = queue.jobs.find(job => job.kind !== 'reload' && job.state === 'running')
  const caps = capsLine(mods)
  const news = [updatesText(attention.updates), caps].filter(
    (part): part is string => part !== undefined,
  )
  const said = new Set(attention.dismissed?.split(' · ') ?? [])
  return {
    ...(running === undefined ? {} : { running }),
    pending: queue.jobs.filter(job => NEEDS_RELOAD.has(job.kind) && isActive(job)).length,
    reloading: reloadJob?.state === 'running',
    reloadOwed: attention.reloadPending && reloadJob === undefined,
    updates: attention.updates,
    capsCount: mods.filter(row => row.capsNew !== undefined).length,
    ...(caps === undefined ? {} : { caps }),
    newsDismissed: news.length > 0 && news.every(part => said.has(part)),
    ...(attention.lastReload === undefined ? {} : { echo: attention.lastReload }),
  }
}

export type Band = {
  /** What was said: a dismissal hides the band until this changes. */
  readonly key: string
  readonly text: string
  /** Offer `[l reload]`: a reload is owed and none is queued. */
  readonly reload: boolean
}

/**
 * The band's one line: shown only when something is
 * actionable and that very thing wasn't dismissed. `isWorking` is the band's
 * `e.props.isWorking`: a reload asked mid-turn waits for the turn to end.
 */
export const bandOf = (
  summary: Summary,
  how: { readonly dismissed?: string | undefined; readonly isWorking: boolean },
): Band | undefined => {
  const parts: string[] = []
  if (summary.running !== undefined) parts.push(`${describeJob(summary.running)}…`)
  if (summary.reloading) {
    parts.push(how.isWorking ? 'reload queued, runs when the turn ends' : 'reloading plugins…')
  }
  const updates = updatesText(summary.updates)
  if (updates !== undefined) parts.push(updates)
  if (summary.caps !== undefined) parts.push(summary.caps)
  if (summary.reloadOwed) parts.push('reload to apply')
  if (parts.length === 0) {
    if (summary.echo === undefined) return undefined
    parts.push(summary.echo)
  }
  const text = `mods · ${parts.join(' · ')}`
  if (how.dismissed === text) return undefined
  return { key: text, text, reload: summary.reloadOwed }
}

/**
 * The status line under the prompt (`$.ui.status`, one per plugin, drawn
 * `modmgr: <text>`): one clause, the most important, since it sits under
 * every prompt. What is under way, then what is owed, then news the person
 * hasn't dismissed (what an update added before how many updates wait);
 * nothing when idle (undefined clears it). The band says the rest.
 */
export const statusLineOf = (summary: Summary): string | undefined => {
  const { running } = summary
  if (running?.kind === 'marketplace-update') return `${describeJob(running)}…`
  if (summary.pending > 0) return `applying ${summary.pending}…`
  if (running !== undefined) return `${describeJob(running)}…`
  if (summary.reloading) return 'reloading plugins…'
  if (summary.reloadOwed) return 'reload to apply'
  if (summary.newsDismissed) return undefined
  // The engine names the plugin before it (`modmgr: …`).
  return summary.caps ?? updatesText(summary.updates)
}

/** The pane's title: `mods`, with news not dismissed (a retitle is an open). */
export const titleOf = (summary: Summary): string => {
  const parts = [PANE_TITLE]
  if (!summary.newsDismissed) {
    const updates = updatesText(summary.updates)
    if (updates !== undefined) parts.push(updates)
    if (summary.capsCount > 0) parts.push(`${summary.capsCount} can do more`)
  }
  return parts.join(' · ')
}

