// The `/mods` dialog: the tabs and a line about the tab, the search field, the
// tab's list (with the detail beside it from SPLIT_MIN_COLUMNS body columns),
// the overlay on top, a line under the list for what is staged and the pager,
// and a footer with the main keys of the moment. It fills
// `scroll.bodyRows`: the list is windowed and a taller overlay is clipped (the
// detail draws compactly), so the header and footer never scroll away.
// Everything drawn comes from `$.state`.

import type { RenderElement, UiPressArgument } from 'claude-code'
import type { Overlay, View } from '../../types/index.d.ts'
import { devRowOf } from '../domain/dev.ts'
import { awaitingAcceptance, detectLine, foundRow, nextSort } from '../domain/discover.ts'
import { healthItemsOf, healthLines, problemCount } from '../domain/health.ts'
import type { KeySurface } from '../domain/keymap.ts'
import { sanitize } from '../domain/sanitize.ts'
import {
  batchLineOf,
  FILTER_KEY,
  filterRows,
  footerRowsFor,
  layoutFor,
  listColumnsFor,
  pagerLabel,
  selectedRow,
  stagedIds,
  whyNoRemove,
  whyNoUpdate,
  windowAround,
} from '../domain/view.ts'
import { Detail, detailRows } from './Detail.tsx'
import { DevDetail, DevList, devDetailRows, Share, shareRows } from './Dev.tsx'
import { FoundDetail, FoundList, foundDetailRows } from './Discover.tsx'
import { HealthItemDetail, HealthList, healthDetailRows } from './Health.tsx'
import { List } from './Installed.tsx'
import { GLYPH, KeyButton, Rule, TONE, type ViewPorts } from './kit.tsx'
import {
  Help,
  helpRows,
  Jobs,
  MarketplaceForm,
  marketplaceRows,
  Review,
  reviewRows,
  Welcome,
  welcomeRows,
} from './overlays.tsx'

export type PaneFrame = {
  readonly bodyColumns: number
  readonly bodyRows: number
  readonly isFocused: boolean
}

/** Keymap actions this version doesn't draw yet: help leaves them out. */
const NOT_YET: ReadonlySet<string> = new Set()

/** From this many body rows the search field is drawn in a box. */
const BOXED_FIELD_MIN_ROWS = 18

/** A key of the moment: what it does, where its hotkey is bound, what it says. */
type Key = {
  readonly action: string
  readonly on: KeySurface
  readonly label: string
  /** Gets the press: a copy targets the surface it came from. */
  readonly onPress: (press: UiPressArgument) => void
}

export const drawPane = async (v: ViewPorts, frame: PaneFrame): Promise<RenderElement> => {
  const [
    view,
    mods,
    detail,
    queue,
    review,
    sync,
    degraded,
    attention,
    page,
    detect,
    devState,
    facts,
  ] = await Promise.all([
    v.read('view'),
    v.read('mods'),
    v.read('detail'),
    v.read('queue'),
    v.read('review'),
    v.read('sync'),
    v.read('degraded'),
    v.read('attention'),
    v.read('catalogPage'),
    v.read('detect'),
    v.read('dev'),
    v.read('health'),
  ])
  const { Box, Button, Text, Input } = v.el
  const discover = view.tab === 'discover'
  const dev = view.tab === 'dev'
  const health = view.tab === 'health'
  const installed = !discover && !dev && !health
  const surface: KeySurface = discover ? 'discover' : dev ? 'dev' : health ? 'health' : 'installed'
  const layout = layoutFor(frame.bodyColumns)
  // A review overlay whose review was just taken (confirm) is already gone: the
  // tree drawn in between must be the final one, or the focus ring set on a row
  // in it is lost when the real list replaces it.
  const stack = review === null ? view.stack.filter(item => item !== 'review') : view.stack
  const top = stack.at(-1)
  const readOnly = degraded.process
  // A missing CLI concerns both tabs; network use only Discover.
  const warning = degraded.process
    ? degraded.reason
    : discover && degraded.network
      ? 'Network use is off: only local catalogues are checked for mods.'
      : undefined
  const status = batchLineOf(queue, attention.lastReload !== undefined)
  const terminal = v.surface === 'terminal'
  const listColumns = layout === 'split' ? listColumnsFor(frame.bodyColumns) : frame.bodyColumns
  // Help, the job log and the welcome are about the whole dialog: they take the
  // whole body (beside the list, the welcome's key would lose the ring to a row).
  const wide = top === 'help' || top === 'jobs' || top === 'welcome'
  const showList = (layout === 'split' && !wide) || top === undefined

  // Installed: rows, the selection, what is staged.
  const rows = filterRows(mods, view.query)
  const selected = selectedRow(view, mods)
  const changing = stagedIds(view, mods)
  const staged = changing.size
  const showStaged = installed && staged > 0 && !readOnly && top !== 'review'
  // Discover: the window of rows `$.state` holds, and the selection in it.
  const found = foundRow(view, page)
  // Dev: its rows, and what validate, test and the session said of them.
  const devRow = devRowOf(view.dev, devState.rows)
  const devHow = { jobs: queue.jobs, failures: devState.failures }
  // Health: every item, from state alone, and the one selected.
  const items = healthItemsOf({
    mods,
    dev: devState,
    attention,
    degraded,
    sync,
    detect,
    queue,
    facts,
  })
  const item = items.find(each => each.key === view.health) ?? items[0]
  const problems = problemCount(items)

  const fieldShown = discover
    ? Input !== undefined && showList && (page.total > 0 || view.search !== '')
    : Input !== undefined && showList && installed && mods.length > 0
  const stopped = readOnly ? undefined : awaitingAcceptance(queue.jobs)
  const split = layout === 'split'
  // Beside the list the detail draws its own keys (toggle, install, validate…);
  // stacked, the footer carries them until Enter opens the detail.
  const itemKeys = !split && top === undefined

  const tabs: readonly { readonly tab: View['tab']; readonly label: string }[] = [
    { tab: 'installed', label: 'Installed' },
    { tab: 'discover', label: 'Discover' },
    { tab: 'dev', label: 'Dev' },
    { tab: 'health', label: problems === 0 ? 'Health' : `Health ${GLYPH.problem}${problems}` },
  ]
  // The tab row's width: a shown tab is its label, another `n: label`. When it
  // and `r: refresh` don't fit, the tabs close up and refresh joins the footer.
  const tabsWidth = tabs.reduce(
    (sum, { tab, label }) => sum + label.length + (view.tab === tab ? 0 : 3),
    0,
  )
  const narrowHeader =
    tabsWidth + 3 * (tabs.length - 1) + 2 + 'r: refresh'.length > frame.bodyColumns
  // The footer's keys: the actions of the moment. Every key is drawn where it
  // belongs (tabs, refresh, search, pager, footer): a hotkey needs a Button,
  // and every Button is a stop of the Tab ring, so none is hidden.
  const keys: Key[] = []
  const add = (key: Omit<Key, 'on'> & { readonly on?: KeySurface }) =>
    keys.push({ on: surface, ...key })
  if (top === undefined && installed && !readOnly) {
    const updatable = mods.filter(row => whyNoUpdate(row) === undefined).length
    if (itemKeys && selected !== undefined) {
      add({ action: 'toggle', label: 'toggle', onPress: () => v.act.toggle() })
      if (whyNoUpdate(selected) === undefined)
        add({ action: 'update', label: 'update', onPress: () => v.act.update() })
      if (whyNoRemove(selected) === undefined)
        add({ action: 'remove', label: 'remove', onPress: () => v.act.remove() })
    }
    if (updatable > 1)
      add({ action: 'update-all', label: 'update all', onPress: () => v.act.updateAll() })
    add({ action: 'undo', label: 'undo', onPress: () => v.act.undo() })
  }
  if (top === undefined && discover) {
    if (itemKeys && !readOnly && found !== undefined)
      add({ action: 'install', label: 'install', onPress: () => v.act.install() })
    // It says what pressing it does next.
    add({
      action: 'sort',
      label: `sort by ${nextSort(view.sort)}`,
      onPress: () => v.act.cycleSort(),
    })
    if (!readOnly)
      add({
        action: 'marketplace-add',
        label: 'marketplace',
        onPress: () => v.act.addMarketplace(),
      })
  }
  if (top === undefined && dev) {
    if (itemKeys && devRow !== undefined) {
      const path = devRow.path
      if (!readOnly) {
        add({ action: 'validate', label: 'validate', onPress: () => v.act.devRun('validate') })
        add({ action: 'test', label: 'test', onPress: () => v.act.devRun('test') })
        add({ action: 'share', label: 'share', onPress: () => v.act.share() })
      }
      add({
        action: 'copy',
        label: 'copy path',
        onPress: press => v.act.copy(path, press.surface),
      })
    }
    if (!readOnly) add({ action: 'reload', label: 'reload', onPress: () => v.act.reload() })
  }
  if (top === undefined && health && !readOnly) {
    add({ action: 'reload', label: 'reload', onPress: () => v.act.reload() })
  }
  if (top === undefined && narrowHeader) {
    add({ action: 'refresh', label: 'refresh', onPress: () => v.act.refresh() })
  }
  // `v` is Dev's validate: a waiting command is reviewed from Installed or Discover.
  if (top === undefined && stopped !== undefined && !dev) {
    add({ action: 'accept', label: 'review the command', onPress: () => v.act.acceptShown() })
  }
  // Jobs and keys go over any view; a review or the marketplace form holds the keys.
  const general: Key[] =
    top === 'review' || top === 'marketplace'
      ? []
      : [
          { action: 'jobs', on: 'pane', label: 'jobs', onPress: () => v.act.overlay('jobs') },
          { action: 'help', on: 'pane', label: 'keys', onPress: () => v.act.overlay('help') },
        ]
  const closeLabel =
    top === undefined ? (terminal ? 'esc close' : 'close') : terminal ? 'esc back' : 'back'
  const hint = frame.isFocused || !terminal ? undefined : 'ctrl+x tab to use the keys'

  // Rows the list may take: the body less every other line drawn. The footer's
  // keys wrap in what the jobs, keys and close group leaves them (a hotkey is
  // painted before its label: `e: toggle`).
  const rightColumns =
    general.reduce((sum, key) => sum + key.label.length + 3 + 2, 0) + closeLabel.length
  const footerRows = footerRowsFor(
    [...keys.map(key => key.label.length + 3), ...(hint === undefined ? [] : [hint.length])],
    Math.max(1, frame.bodyColumns - rightColumns - 2),
  )
  const boxedField = fieldShown && frame.bodyRows >= BOXED_FIELD_MIN_ROWS
  const chrome =
    2 +
    (warning === undefined ? 0 : 1) +
    (fieldShown ? (boxedField ? 3 : 1) : 0) +
    (view.notice === undefined ? 0 : 1) +
    (status === undefined ? 0 : 1) +
    1 +
    footerRows
  // Under the list, one line holds what is staged and the pager. The pager's
  // keys come after the field in the Tab ring: drawn above it, their coming
  // and going as the search narrows moved the ring off the field.
  const itemCount = health
    ? items.length
    : dev
      ? devState.rows.length
      : discover
        ? page.matched
        : rows.length
  // The rows the whole list takes: Health's group names, Discover's two rows an entry.
  const fullRows = health
    ? itemCount +
      items.filter((each, index) => index === 0 || items[index - 1]?.group !== each.group).length
    : discover
      ? itemCount * 2
      : itemCount
  const paging = showList && fullRows > frame.bodyRows - chrome - (showStaged ? 1 : 0)
  // Too narrow for both, the pager wraps under what is staged (its widest label counted).
  const stagedWidth = `${staged} staged changes  s: review and apply`.length
  const widestPager = pagerLabel({ start: itemCount - 1, end: itemCount }, itemCount) ?? ''
  const pagerWidth = `${widestPager}  g: first  b: last`.length
  const underRows = showStaged
    ? paging
      ? footerRowsFor([stagedWidth, pagerWidth], frame.bodyColumns)
      : 1
    : paging
      ? 1
      : 0
  const listRows = Math.max(3, frame.bodyRows - chrome - underRows)

  // The list, windowed around the selection, and its pager.
  let list: RenderElement
  let pager: string | undefined
  if (health) {
    const shown = healthLines(items, item === undefined ? 0 : items.indexOf(item), listRows)
    pager = pagerLabel(shown.items, items.length)
    list = HealthList(v, shown.lines, {
      columns: listColumns,
      focusKey: item?.key,
      stacked: !split,
      before: items.slice(0, shown.items.start),
      after: items.slice(shown.items.end),
    })
  } else if (dev) {
    const at = devRow === undefined ? 0 : devState.rows.indexOf(devRow)
    const window = windowAround(devState.rows.length, at, listRows)
    pager = pagerLabel(window, devState.rows.length)
    list = DevList(v, devState.rows, {
      ...devHow,
      columns: listColumns,
      window,
      focusKey: devRow?.key,
      loading: devState.loading && devState.at === undefined,
      beside: split,
    })
  } else if (discover) {
    // Each entry takes two rows: its name, then what it says it does.
    const at = found === undefined ? 0 : page.rows.indexOf(found)
    const window = windowAround(page.rows.length, at, Math.floor(listRows / 2))
    list = FoundList(v, page, {
      view,
      columns: listColumns,
      window,
      focusId: found?.id,
      networkOff: degraded.network,
      checking: detect.running,
      beside: split,
    })
    pager =
      page.matched > window.end - window.start
        ? pagerLabel(
            { start: page.offset + window.start, end: page.offset + window.end },
            page.matched,
          )
        : undefined
  } else {
    const window = windowAround(
      rows.length,
      selected === undefined ? 0 : rows.indexOf(selected),
      listRows,
    )
    pager = pagerLabel(window, rows.length)
    list = List(v, rows, {
      view,
      staged: changing,
      columns: listColumns,
      window,
      focusId: selected?.id,
      loading: sync.at === undefined && sync.error === undefined,
      total: mods.length,
      beside: split,
    })
  }

  const under = stack.at(-2)
  const detailSurface: KeySurface = discover
    ? 'discover-detail'
    : dev
      ? 'dev-detail'
      : health
        ? 'health'
        : 'detail'
  const surfaceOf = (overlay: Overlay | undefined): KeySurface =>
    overlay === undefined
      ? surface
      : overlay === 'detail'
        ? detailSurface
        : overlay === 'share'
          ? 'share'
          : overlay === 'review'
            ? 'review'
            : overlay === 'jobs'
              ? 'jobs'
              : surface
  // Beside the list the detail's keys are mounted too.
  // Help takes the whole body: the detail beside the list isn't drawn under it.
  const helpSurfaces: KeySurface[] = ['pane', surfaceOf(under)]
  const refused = degraded.acceptCommand
  const overlay = (which: Overlay | undefined): RenderElement | null => {
    if (which === 'review' && review !== null) return Review(v, review, mods, { refused })
    if (which === 'help') return Help(v, helpSurfaces, NOT_YET, frame.bodyColumns)
    if (which === 'jobs') return Jobs(v, queue.jobs, listRows)
    if (which === 'marketplace') return MarketplaceForm(v)
    if (which === 'share') return Share(v, devState.share)
    if (which === 'welcome') return Welcome(v)
    return null
  }

  // Beside the list: what the list, the divider and their gaps leave.
  const detailColumns = split ? frame.bodyColumns - listColumns - 3 : frame.bodyColumns
  const sized = { readOnly, rows: listRows, columns: detailColumns }
  const detailHow = { ...sized, row: selected, detail, staged: changing, view }
  const detailView = () =>
    discover
      ? FoundDetail(v, found, sized)
      : dev
        ? DevDetail(v, devRow, { ...devHow, ...sized })
        : health
          ? HealthItemDetail(v, item)
          : Detail(v, detailHow)
  /** Rows the overlay on top draws, to clip it to the body (Jobs sizes itself). */
  const overlayRows = (which: Overlay | undefined): number =>
    which === 'review' && review !== null
      ? reviewRows(v, review, mods, frame.bodyColumns, { refused })
      : which === 'help'
        ? helpRows(helpSurfaces, NOT_YET, frame.bodyColumns)
        : which === 'marketplace'
          ? marketplaceRows
          : which === 'share'
            ? shareRows(devState.share, frame.bodyColumns)
            : which === 'welcome'
              ? welcomeRows(frame.bodyColumns)
              : which === 'detail'
                ? discover
                  ? foundDetailRows(v, found, sized)
                  : dev
                    ? devDetailRows(v, devRow, { ...devHow, ...sized })
                    : health
                      ? healthDetailRows(item, frame.bodyColumns)
                      : detailRows(v, detailHow)
                : 0
  /** A tall overlay, held to the body's rows so the footer stays in view. */
  const clipped = (element: RenderElement, height: number): RenderElement =>
    height <= listRows ? (
      element
    ) : (
      <Box flexDirection="column" height={listRows} overflow="hidden">
        <Box flexDirection="column" flexShrink={0}>
          {element}
        </Box>
      </Box>
    )

  const body =
    split && !wide ? (
      // Clipped to the list's rows, so the header and footer stay in view; the
      // whole detail is one Enter away. The detail beside the list carries its keys.
      <Box flexDirection="row" columnGap={1} height={listRows} overflow="hidden">
        <Box flexDirection="column" width={listColumns} flexShrink={0} overflow="hidden">
          <Box flexDirection="column" flexShrink={0}>
            {list}
          </Box>
        </Box>
        <Box flexDirection="column" width={1} flexShrink={0}>
          {Array.from({ length: listRows }, (_, index) => (
            <Text key={`divider:${index}`} dimColor>
              │
            </Text>
          ))}
        </Box>
        <Box flexDirection="column" flexGrow={1} flexShrink={1} overflow="hidden">
          <Box flexDirection="column" flexShrink={0}>
            {overlay(top) ?? detailView()}
          </Box>
        </Box>
      </Box>
    ) : top === undefined ? (
      list
    ) : top === 'detail' ? (
      clipped(detailView(), overlayRows(top))
    ) : (
      clipped(overlay(top) ?? list, overlayRows(top))
    )

  const button = (key: Key) =>
    KeyButton(v, { action: key.action, on: key.on, label: key.label, onPress: key.onPress })
  const on = mods.filter(row => row.enabled).length
  // The tab shown is a title; the others are its number keys.
  const tabRow = tabs.map(({ tab, label }) =>
    view.tab === tab ? (
      <Box key={`tab:${tab}`} flexShrink={0}>
        <Text bold underline color={TONE.accent}>
          {label}
        </Text>
      </Box>
    ) : (
      <Box key={`tab:${tab}`} flexShrink={0}>
        {KeyButton(v, {
          action: `tab.${tab}`,
          on: 'pane',
          label,
          dim: true,
          onPress: () => v.act.tab(tab),
        })}
      </Box>
    ),
  )
  const failing = devState.rows.filter(row => devState.failures[row.name] !== undefined).length
  const updates = mods.filter(row => row.updateTo !== undefined).length
  const count = (n: number, one: string, many: string) =>
    `${n.toLocaleString('en-US')} ${n === 1 ? one : many}`
  const meta = health
    ? problems === 0
      ? 'Nothing needs you.'
      : `${count(problems, 'problem', 'problems')} to look at`
    : dev
      ? [
          count(devState.rows.length, 'mod', 'mods') + ' under development',
          failing === 0 ? '' : `${failing} failing`,
        ]
          .filter(part => part !== '')
          .join(' · ')
      : discover
        ? [
            view.search === '' ? '' : `${page.matched.toLocaleString('en-US')} matching`,
            detectLine(detect) ?? '',
          ]
            .filter(part => part !== '')
            .join(' · ')
        : [
            `${on} of ${count(mods.length, 'mod', 'mods')} on`,
            updates === 0 ? '' : count(updates, 'update', 'updates'),
          ]
            .filter(part => part !== '')
            .join(' · ')
  const stale = discover ? page.loading : dev ? devState.loading : sync.refreshing
  const field =
    fieldShown && Input !== undefined ? (
      <Box flexDirection="row" flexGrow={1}>
        <Text dimColor>⌕ </Text>
        <Box flexGrow={1}>
          <Input
            key={FILTER_KEY}
            placeholder={
              discover
                ? detect.found === 0
                  ? 'Search mods'
                  : `Search ${count(detect.found, 'mod', 'mods')}`
                : `Filter ${count(mods.length, 'mod', 'mods')}`
            }
            value={discover ? view.search : view.query}
            onInput={value => v.act.filter(value)}
            onSubmit={value => v.act.filter(value)}
          />
        </Box>
        {KeyButton(v, {
          action: 'filter',
          on: surface,
          label: discover ? 'search' : 'filter',
          dim: true,
          onPress: () => v.act.focusFilter(),
        })}
      </Box>
    ) : null

  return (
    <Box flexDirection="column" height={frame.bodyRows}>
      <Box flexDirection="row" justifyContent="space-between" height={1} overflow="hidden">
        <Box flexDirection="row" columnGap={narrowHeader ? 2 : 3} flexShrink={1}>
          {tabRow}
        </Box>
        <Box flexDirection="row" columnGap={1} flexShrink={0}>
          {stale ? (
            <Text dimColor>{GLYPH.stale}</Text>
          ) : installed && sync.error !== undefined ? (
            <Text color={TONE.warn}>{GLYPH.problem} couldn't refresh</Text>
          ) : null}
          {top === undefined && !narrowHeader
            ? KeyButton(v, {
                action: 'refresh',
                on: surface,
                label: 'refresh',
                dim: true,
                onPress: () => v.act.refresh(),
              })
            : null}
        </Box>
      </Box>
      <Box height={1} overflow="hidden">
        <Text dimColor wrap="truncate-end">
          {meta}
        </Text>
      </Box>
      {warning === undefined ? null : (
        <Text color={TONE.warn} wrap="truncate-end">
          {sanitize(warning, { max: 300 })}
        </Text>
      )}
      {field === null ? null : boxedField ? (
        <Box borderStyle="round" borderDimColor paddingX={1} flexDirection="row">
          {field}
        </Box>
      ) : (
        <Box flexDirection="row">{field}</Box>
      )}
      <Box flexDirection="column" flexGrow={1}>
        {body}
      </Box>
      {underRows > 0 ? (
        <Box flexDirection="row" justifyContent="space-between" columnGap={2} flexWrap="wrap">
          <Box flexDirection="row" gap={2} flexShrink={0}>
            {showStaged ? (
              <Text color={TONE.warn}>
                {staged} staged {staged === 1 ? 'change' : 'changes'}
              </Text>
            ) : null}
            {showStaged
              ? KeyButton(v, {
                  action: 'apply',
                  on: 'installed',
                  label: 'review and apply',
                  onPress: () => v.act.apply(),
                })
              : null}
          </Box>
          {paging && pager !== undefined ? (
            <Box flexDirection="row" columnGap={2} flexShrink={0}>
              <Text dimColor>{pager}</Text>
              {top === undefined
                ? KeyButton(v, {
                    action: 'page.first',
                    on: surface,
                    label: 'first',
                    dim: true,
                    onPress: () => v.act.edge('first'),
                  })
                : null}
              {top === undefined
                ? KeyButton(v, {
                    action: 'page.last',
                    on: surface,
                    label: 'last',
                    dim: true,
                    onPress: () => v.act.edge('last'),
                  })
                : null}
            </Box>
          ) : null}
        </Box>
      ) : null}
      {view.notice === undefined ? null : (
        <Text dimColor wrap="truncate-end">
          {sanitize(view.notice, { max: 300 })}
        </Text>
      )}
      {status === undefined ? null : (
        <Text
          color={status.tone === 'error' ? TONE.bad : status.tone === 'ok' ? TONE.ok : TONE.accent}
          wrap="truncate-end"
        >
          {status.tone === 'error' ? GLYPH.failed : status.tone === 'ok' ? GLYPH.ok : GLYPH.stale}{' '}
          {status.text}
        </Text>
      )}
      {Rule(v, frame.bodyColumns)}
      <Box flexDirection="row" justifyContent="space-between" columnGap={2}>
        <Box flexDirection="row" columnGap={2} flexWrap="wrap" flexShrink={1}>
          {keys.map(button)}
          {hint === undefined ? null : <Text dimColor>{hint}</Text>}
        </Box>
        <Box flexDirection="row" columnGap={2} flexShrink={0}>
          {general.map(key => KeyButton(v, { ...key, dim: true }))}
          {top === undefined ? (
            <Button
              key="act:close"
              plain
              dimColor
              label={closeLabel}
              onPress={() => v.act.close()}
            />
          ) : (
            <Button key="act:back" plain dimColor label={closeLabel} onPress={() => v.act.back()} />
          )}
        </Box>
      </Box>
    </Box>
  )
}

files.types/index.d.ts:
// modmgr's state contract. Session-scoped values in `$.state`
// that drive rendering and survive `/reload-plugins`. Every key is `Shaped`:
// its atom names a tag (`'queue/1'`), so a modmgr update that changes a
// value's type reads the old value as absent instead of misreading it.

export type PluginId = string
export type Scope = 'user' | 'project' | 'local' | 'managed'
export type Origin =
  | 'marketplace'
  | 'skills-dir'
  | 'folder-marketplace'
  | 'plugin-dir'
  | 'env-dir'
  | 'dev-session'
export type Reach = 'machine' | 'network' | 'session' | 'model' | 'tools' | 'plugins' | 'display'
export type Capabilities = {
  events: string[]
  calls: string[]
  envReads: string[]
  reach: Reach[]
  notable: string[]
}

export type ModRow = {
  id: PluginId
  name: string
  version?: string
  origin: Origin
  scope?: Scope
  enabled: boolean
  projectEnabled?: boolean
  toggleable: boolean
  notableCount: number
  updateTo?: string
  problems: number
  mixed: boolean
  /** Notable capabilities its last update added, until its detail is opened. */
  capsNew?: CapsNew
}

/** What a version change added to a mod's notable list, and the version it came from. */
export type CapsNew = { since: string; added: string[] }

export type ModDetail = ModRow & {
  description?: string
  root?: string
  caps?: Capabilities
  mixedCounts?: { skills: number; agents: number; mcp: number }
  tokens?: number
  dataBytes?: number
  validate?: { errors: number; warnings: number; at: number }
  dev?: { failures: number; lastReason?: string; lastAt?: number; test?: 'pass' | 'fail' }
}

export type CatalogKind = 'mod' | 'hooks' | 'plain' | 'unknown'

export type CatalogRow = {
  id: PluginId
  name: string
  marketplace: string
  installs?: number
  kind: CatalogKind
  blurb: string
  version?: string
  /** Where it comes from, in a few words. */
  source: string
  /** What it can do, when modmgr read it before installing (a local source); notable ids. */
  notable?: string[]
  /** Its files are on disk (a folder in its marketplace): modmgr can read it before installing. */
  local?: boolean
  /** A local entry modmgr couldn't read: why (`r` tries again). */
  unread?: string
}

export type JobKind =
  | 'install'
  | 'update'
  | 'remove'
  | 'enable'
  | 'disable'
  | 'validate'
  | 'test'
  | 'reload'
  | 'marketplace-add'
  | 'marketplace-update'

export type JobState = 'queued' | 'running' | 'ok' | 'failed' | 'cancelled' | 'interrupted'

export type Job = {
  id: string
  batch?: string
  kind: JobKind
  target?: PluginId
  args?: { scope?: Scope; acceptSha?: string; path?: string; source?: string; keepData?: boolean }
  state: JobState
  startedAt?: number
  endedAt?: number
  tail: string[]
  error?: { kind: string; message: string }
  /** It succeeded without changing anything (already so, already up to date): no reload owed. */
  unchanged?: boolean
  /** A validate: what it found (the tail lists them). */
  report?: { errors: number; warnings: number }
  /** A remove: whether the CLI said it kept the mod's data folder (`keptData`), when it said. */
  keptData?: boolean
  /**
   * An install or update stopped on a marketplace-declared command: what
   * the CLI showed, for the review that accepts it. Untrusted text.
   */
  shown?: {
    kind: 'command_source' | 'entry_helper'
    command: string
    sha256: string
    /** The command was longer than modmgr keeps: it can't be shown whole, so not accepted here. */
    truncated?: boolean
  }
}

export type Tab = 'installed' | 'discover' | 'dev' | 'health'
export type Overlay = 'detail' | 'review' | 'help' | 'jobs' | 'marketplace' | 'share' | 'welcome'

export type View = {
  tab: Tab
  selected?: PluginId
  stack: Overlay[]
  /** Installed's filter. */
  query: string
  /** Discover's search and sort. */
  search: string
  sort: 'installs' | 'name' | 'marketplace'
  /** The catalogue entry Discover has selected. */
  found?: PluginId
  /** The dev mod Dev has selected (its `DevRow.key`). */
  dev?: string
  /** The item Health has selected (its key). */
  health?: string
  /** Staged toggles: what each mod will be after apply. */
  staged: Record<PluginId, boolean>
  /** One short line the pane shows until the next action (a copy, a refused focus). */
  notice?: string
}

/** What a review would do to one mod. */
export type ReviewOp = 'enable' | 'disable' | 'install' | 'remove' | 'update'

export type ReviewTarget = {
  id: PluginId
  op: ReviewOp
  scope?: Scope
  /** The version it is at now (an update's "from"). */
  version?: string
  /** A reinstall (undo of a remove): whether that remove kept the mod's data. */
  keptData?: boolean
}

/**
 * One confirm at a time (a plain value). Every action that runs new code
 * or removes something passes through one.
 */
export type ReviewRequest = {
  action: 'toggle' | 'update' | 'remove' | 'undo' | 'install' | 'marketplace'
  targets: ReviewTarget[]
  /** Notable capabilities of what turns on or comes back, as lines. */
  notable: string[]
  declaredCommand?: { text: string; sha256: string; truncated?: boolean }
  headersHelper?: { text: string; sha256: string; truncated?: boolean }
  changesRepoFile: boolean
  /** The other parts of what turns off or is removed: skills, agents, MCP servers. */
  parts?: { skills: number; agents: number; mcp: number }
  /** An update refreshes these marketplaces first. */
  marketplaces?: string[]
  /** A remove keeps the mod's data folder (the default), so undo restores it as it was. */
  keepData?: boolean
  /** A remove: the size of the mod's data folder, when it has one. */
  dataBytes?: number
  /** An undo: the batch it undoes; confirm queues it only while that is still the batch to undo. */
  undoes?: string
  /** An install: modmgr couldn't see what it can do before it's installed (a remote source). */
  uninspected?: boolean
  /** An install of a local entry modmgr tried to read and couldn't: why. */
  unreadable?: string
  /** A marketplace to add (`claude plugin marketplace add <source>`). */
  source?: string
}

export type Attention = {
  updates: number
  problems: number
  reloadPending: boolean
  capsChanged: number
  /** The band line the person dismissed; the band returns once its line changes. */
  dismissed?: string
  /** The CLI's answer to the last reload ("Reloaded: …"), echoed in the band for a while. */
  lastReload?: string
}

export type Degraded = {
  process: boolean
  network: boolean
  /** Set after Claude Code refused a declared-command acceptance from this session. */
  acceptCommand: boolean
  reason?: string
}

/**
 * The job queue and the module that drives it. A module takes the queue over
 * at `session.start` (setting `owner`); a runner whose owner was replaced stops
 * claiming jobs, so an old module's in-flight work never races the new one.
 */
export type JobQueue = { owner: string; jobs: Job[] }

/** The installed list's refresh, for the title's stale marker. */
export type Sync = {
  refreshing: boolean
  at?: number
  error?: { kind: string; message: string }
  /** `list --json` entries modmgr could not read. */
  skipped: number
}

/**
 * The part of the catalogue Discover draws (never all of it): at most a window of rows
 * around the selection, `offset` the first one's place among the `matched`.
 */
export type CatalogPage = {
  rows: CatalogRow[]
  total: number
  matched: number
  offset: number
  loading: boolean
  error?: string
}
export type DetectProgress = {
  checked: number
  total: number
  found: number
  running: boolean
  /** When the hosted index whose kinds were taken was built (ms); absent when none was read. */
  indexAt?: number
}

/**
 * How a mod under development is loaded: from this
 * session's mods folder, a `--plugin-dir` (found through its commands), a
 * `CLAUDE_CODE_PLUGIN_DIRS` folder, the skills folder, or a folder marketplace.
 */
export type DevHow =
  | 'session-folder'
  | 'plugin-dir'
  | 'env-dir'
  | 'skills-dir'
  | 'folder-marketplace'

export type DevRow = {
  /** Stable: its folder. */
  key: string
  name: string
  how: DevHow
  /** Its plugin id when the CLI lists it (`name@inline`, `name@skills-dir`, `name@<marketplace>`). */
  id?: PluginId
  /** Its folder, absolute. */
  path: string
  version?: string
  enabled?: boolean
}

/** A plugin's failures the session reported while hot-reloading it. */
export type DevFailures = {
  count: number
  lastReason: string
  lastAt: number
  /** Its folder, when a notice named a file of its hooks. */
  folder?: string
}

/** How to share a dev mod (`p`), for the share overlay. */
export type DevShare = {
  /** The row it is for. */
  key: string
  name: string
  /** `/plugin install <mod> --marketplace <owner>/<repo>`. */
  line: string
  /** `line` names a real repository. */
  complete: boolean
  /** The marketplace file to write, when none lists the mod. */
  snippet?: string
  notes: string[]
}

export type DevState = {
  rows: DevRow[]
  /** By plugin name, as the session's notices name it. */
  failures: Record<string, DevFailures>
  loading: boolean
  at?: number
  share?: DevShare
}

/** A note that two or more enabled mods hook an event whose order decides the result. */
export type ChainNoteRow = { event: string; text: string }

/**
 * What Health shows beyond the other keys, gathered when it is
 * opened or refreshed: notes on hook order, the last hook failures the debug
 * log names, the detector's budget, the store's size, the update checks.
 */
export type HealthFacts = {
  at?: number
  chain: ChainNoteRow[]
  /** By plugin name: the last `hook failed closed` line's event and error kind. */
  logged: Record<string, string>
  /**
   * This session's debug log (`--debug`, `<config>/debug/<session id>.txt`):
   * none, read, or too large to read here (over 4 MiB), with its path.
   */
  debugLog: { state: 'none' | 'read' | 'too-big'; path?: string }
  detector: { spent: number; budget: number; remote: boolean; why?: string }
  cache: { bytes: number; full: boolean }
  updates: { at?: number; every: number; off?: string }
}

declare module 'claude-code' {
  interface PluginState {
    modmgr: {
      mods: Shaped<ModRow[]>
      detail: Shaped<ModDetail | null>
      catalogPage: Shaped<CatalogPage>
      detect: Shaped<DetectProgress>
      queue: Shaped<JobQueue>
      sync: Shaped<Sync>
      view: Shaped<View>
      review: Shaped<ReviewRequest | null>
      attention: Shaped<Attention>
      degraded: Shaped<Degraded>
      dev: Shaped<DevState>
      health: Shaped<HealthFacts>
    }
  }
}

files.hooks/domain/cli-results.ts:
// Parses every `claude plugin … --json` answer modmgr reads into typed
// values. Shapes come from real captures in
// test/domain/fixtures/cli-runs.ts. Unknown fields are ignored; an entry that
// fails its shape check is skipped and counted, never fatal: the CLI's output
// changes between releases.

import {
  type AbsolutePath,
  type PluginId,
  parseAbsolutePath,
  parsePluginId,
  parseSha256,
  SCOPES,
  type Scope,
  type Sha256,
} from './ids.ts'
import { arr, bool, compact, isRecord, type JsonRecord, num, parseJson, rec, str } from './json.ts'
import { fail, ok, type Result } from './result.ts'
import { sanitize } from './sanitize.ts'

/** What a service hands in: one finished `claude plugin …` process. */
export type CliRun = { readonly exitCode: number; readonly stdout: string; readonly stderr: string }

/** `scope: "session"` marks a `CLAUDE_CODE_PLUGIN_DIRS` folder (`<name>@inline`). */
export type InstalledScope = Scope | 'session'

export type InstalledEntry = {
  readonly id: PluginId
  readonly version?: string
  readonly scope: InstalledScope
  readonly enabled: boolean
  readonly installPath?: AbsolutePath
  /** Folder-marketplace plugins are read from this folder. */
  readonly readFromFolder?: AbsolutePath
  readonly folderVersion?: string
  readonly installedAt?: string
  readonly lastUpdated?: string
  readonly projectEnabled?: boolean
  readonly projectPath?: AbsolutePath
  /** From `--data-size`, present only when the data folder exists. */
  readonly dataBytes?: number
}

export type CatalogSource =
  | { readonly kind: 'relative'; readonly path: string }
  | { readonly kind: 'url'; readonly url: string; readonly sha?: string }
  | {
      readonly kind: 'git-subdir'
      readonly url: string
      readonly path: string
      readonly ref?: string
      readonly sha?: string
    }
  | { readonly kind: 'github'; readonly repo: string; readonly sha?: string }
  | { readonly kind: 'command'; readonly command: string }
  | { readonly kind: 'other'; readonly type: string }

export type CatalogEntry = {
  readonly id: PluginId
  readonly name: string
  readonly description: string
  readonly marketplace: string
  readonly source: CatalogSource
  /** Null in the CLI for most entries today; absent here then. */
  readonly installs?: number
  readonly version?: string
}

export type Parsed<T> = { readonly items: T[]; readonly skipped: number }

export type ShownCommand = {
  readonly kind: 'command_source' | 'entry_helper'
  readonly pluginId: string
  /** Shown verbatim to the person, after sanitising for display only. */
  readonly command: string
  readonly mode?: string
  readonly archiveUrl?: string
  readonly catalogRevision: string
  readonly sha256: Sha256
  readonly acceptCommandMatched?: boolean
}

export type OpDone = {
  readonly status: 'done'
  readonly command: string
  readonly pluginId?: PluginId
  readonly scope?: string
  readonly message: string
  /** The CLI found it already so (`already_in_goal_state`): nothing changed. */
  readonly unchanged: boolean
  readonly update?: { readonly outcome: string; readonly from?: string; readonly to?: string }
  /** `uninstall`: whether the data folder was kept, as the CLI says. */
  readonly keptData?: boolean
}

/** A declared command must be accepted first; `changed` when a given sha no longer matched. */
export type OpNeedsAcceptance = {
  readonly status: 'needs-acceptance'
  readonly shown: ShownCommand
  readonly changed: boolean
  readonly message: string
}

export type OpOutcome = OpDone | OpNeedsAcceptance

export type Marketplace = {
  readonly name: string
  readonly source: string
  readonly location?: string
  /** Where its catalogue and relative plugin folders sit on disk (a clone or the folder itself). */
  readonly installLocation?: AbsolutePath
}

export type Details = {
  readonly skills: number
  readonly agents: number
  readonly hooks: number
  readonly mcp: number
  readonly lsp: number
  readonly tokens?: number
}

const MESSAGE_MAX = 500
const IGNORED_IN_SESSION = /--accept-command is ignored inside a Claude Code session/

/** The last stdout line that parses as a JSON object (human lines may precede it). */
export const lastJsonObject = (stdout: string): JsonRecord | undefined => {
  const lines = stdout.split('\n')
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    const line = lines[i]?.trim()
    if (line?.startsWith('{')) {
      const value = parseJson(line)
      if (isRecord(value)) return value
    }
  }
  return undefined
}

const firstLine = (text: string): string =>
  sanitize(
    text
      .split('\n')
      .map(line => line.replace(/^[✘✔⚠❯]\s*/u, '').trim())
      .find(line => line.length > 0) ?? '',
    { max: MESSAGE_MAX },
  )

const noJson = (run: CliRun): Result<never> =>
  run.exitCode === 0
    ? fail('parse', 'the CLI printed no JSON result')
    : fail('cli-failed', firstLine(run.stderr) || firstLine(run.stdout) || `exit ${run.exitCode}`)

const parseWhole = (run: CliRun): Result<unknown> => {
  const value = parseJson(run.stdout)
  if (value !== undefined) return ok(value)
  return noJson(run)
}

const optionalPath = (record: JsonRecord, key: string): AbsolutePath | undefined => {
  const parsed = parseAbsolutePath(str(record, key))
  return parsed.ok ? parsed.value : undefined
}

const installedScope = (value: string | undefined): InstalledScope | undefined =>
  value === 'session' || (SCOPES as readonly (string | undefined)[]).includes(value)
    ? (value as InstalledScope)
    : undefined

export const parseInstalledEntry = (value: unknown): InstalledEntry | undefined => {
  if (!isRecord(value)) return undefined
  const id = parsePluginId(str(value, 'id'))
  const scope = installedScope(str(value, 'scope'))
  const enabled = bool(value, 'enabled')
  if (!id.ok || scope === undefined || enabled === undefined) return undefined
  return compact({
    id: id.value,
    version: str(value, 'version'),
    scope,
    enabled,
    installPath: optionalPath(value, 'installPath'),
    readFromFolder: optionalPath(value, 'readFromFolder'),
    folderVersion: str(value, 'folderVersion'),
    installedAt: str(value, 'installedAt'),
    lastUpdated: str(value, 'lastUpdated'),
    projectEnabled: bool(value, 'projectEnabled'),
    projectPath: optionalPath(value, 'projectPath'),
    dataBytes: (() => {
      const size = rec(value, 'dataDirSize')
      return size === undefined ? undefined : num(size, 'bytes')
    })(),
  })
}

const parseEach = <T>(
  values: readonly unknown[],
  one: (v: unknown) => T | undefined,
): Parsed<T> => {
  const items: T[] = []
  for (const value of values) {
    const item = one(value)
    if (item !== undefined) items.push(item)
  }
  return { items, skipped: values.length - items.length }
}

/** `claude plugin list --json [--data-size]`. */
export const parseInstalledList = (run: CliRun): Result<Parsed<InstalledEntry>> => {
  const whole = parseWhole(run)
  if (!whole.ok) return whole
  if (!Array.isArray(whole.value)) return fail('parse', 'list --json is not an array')
  return ok(parseEach(whole.value, parseInstalledEntry))
}

export const parseCatalogSource = (value: unknown): CatalogSource => {
  if (typeof value === 'string') return { kind: 'relative', path: value }
  if (!isRecord(value)) return { kind: 'other', type: typeof value }
  const type = str(value, 'source') ?? 'unknown'
  const url = str(value, 'url')
  const sha = str(value, 'sha')
  if (type === 'url' && url !== undefined) return compact({ kind: 'url' as const, url, sha })
  const path = str(value, 'path')
  if (type === 'git-subdir' && url !== undefined && path !== undefined) {
    return compact({ kind: 'git-subdir' as const, url, path, ref: str(value, 'ref'), sha })
  }
  const repo = str(value, 'repo')
  if (type === 'github' && repo !== undefined) {
    return compact({ kind: 'github' as const, repo, sha })
  }
  const command = str(value, 'command')
  if (type === 'command' && command !== undefined) return { kind: 'command', command }
  return { kind: 'other', type: sanitize(type, { max: 40 }) }
}

export const parseCatalogEntry = (value: unknown): CatalogEntry | undefined => {
  if (!isRecord(value)) return undefined
  const id = parsePluginId(str(value, 'pluginId'))
  const name = str(value, 'name')
  const marketplace = str(value, 'marketplaceName')
  if (!id.ok || name === undefined || marketplace === undefined) return undefined
  const installs = num(value, 'installCount')
  return compact({
    id: id.value,
    name,
    description: str(value, 'description') ?? '',
    marketplace,
    source: parseCatalogSource(value.source),
    installs: installs !== undefined && installs >= 0 ? Math.floor(installs) : undefined,
    version: str(value, 'version'),
  })
}

/** `claude plugin list --json --available`: `available` excludes installed plugins. */
export const parseAvailable = (
  run: CliRun,
): Result<{ installed: Parsed<InstalledEntry>; available: Parsed<CatalogEntry> }> => {
  const whole = parseWhole(run)
  if (!whole.ok) return whole
  if (!isRecord(whole.value)) return fail('parse', 'list --available is not an object')
  const installed = arr(whole.value, 'installed')
  const available = arr(whole.value, 'available')
  if (installed === undefined || available === undefined) {
    return fail('parse', 'list --available lacks installed or available')
  }
  return ok({
    installed: parseEach(installed, parseInstalledEntry),
    available: parseEach(available, parseCatalogEntry),
  })
}

/** `claude plugin marketplace list --json`. */
export const parseMarketplaces = (run: CliRun): Result<Parsed<Marketplace>> => {
  const whole = parseWhole(run)
  if (!whole.ok) return whole
  if (!Array.isArray(whole.value)) return fail('parse', 'marketplace list is not an array')
  return ok(
    parseEach(whole.value, value => {
      if (!isRecord(value)) return undefined
      const name = str(value, 'name')
      const source = str(value, 'source')
      if (name === undefined || source === undefined) return undefined
      return compact({
        name,
        source,
        location: str(value, 'repo') ?? str(value, 'url') ?? str(value, 'path'),
        installLocation: optionalPath(value, 'installLocation'),
      })
    }),
  )
}

export const parseShownCommand = (value: unknown): ShownCommand | undefined => {
  if (!isRecord(value)) return undefined
  const kind = str(value, 'kind')
  const pluginId = str(value, 'pluginId')
  const command = str(value, 'command')
  const catalogRevision = str(value, 'catalogRevision')
  const sha = parseSha256(str(value, 'sha256'))
  if (
    (kind !== 'command_source' && kind !== 'entry_helper') ||
    pluginId === undefined ||
    command === undefined ||
    catalogRevision === undefined ||
    !sha.ok
  ) {
    return undefined
  }
  return compact({
    kind: kind === 'entry_helper' ? ('entry_helper' as const) : ('command_source' as const),
    pluginId,
    command,
    mode: str(value, 'mode'),
    archiveUrl: str(value, 'archiveUrl'),
    catalogRevision,
    sha256: sha.value,
    acceptCommandMatched: bool(value, 'acceptCommandMatched'),
  })
}

/**
 * One result line of `install | update | uninstall | enable | disable |
 * marketplace add | marketplace update … --json`.
 */
export const parseOpResult = (run: CliRun): Result<OpOutcome> => {
  const line = lastJsonObject(run.stdout)
  // Said with or without a result line: the acceptance was refused here (the
  // CLI refuses it when its environment carries CLAUDECODE).
  if (IGNORED_IN_SESSION.test(run.stdout) || IGNORED_IN_SESSION.test(run.stderr)) {
    const code = line === undefined ? undefined : str(line, 'failureCode')
    return fail('rejected', 'Claude Code ignored the acceptance from here', code)
  }
  if (line === undefined) return noJson(run)
  const message = sanitize(str(line, 'message') ?? '', { max: MESSAGE_MAX })
  const command = str(line, 'command') ?? 'unknown'
  const code = str(line, 'failureCode')
  const shown = parseShownCommand(line.shownCommand)

  if (shown !== undefined && str(line, 'outcome') !== 'ok') {
    if (shown.acceptCommandMatched === true) {
      return fail('rejected', message || 'the declared command was not accepted', code)
    }
    return ok({
      status: 'needs-acceptance',
      shown,
      changed: shown.acceptCommandMatched === false,
      message,
    })
  }

  const unchanged = code === 'already_in_goal_state' || bool(line, 'alreadyInGoalState') === true
  if (str(line, 'outcome') !== 'ok' && !unchanged) {
    return fail('cli-failed', message || `${command} failed`, code)
  }
  const pluginId = parsePluginId(str(line, 'pluginId') ?? str(line, 'plugin'))
  const updateOutcome = str(line, 'updateOutcome')
  return ok(
    compact({
      status: 'done' as const,
      command,
      pluginId: pluginId.ok ? pluginId.value : undefined,
      scope: str(line, 'scope'),
      message,
      unchanged,
      keptData: bool(line, 'keptData'),
      update:
        updateOutcome === undefined
          ? undefined
          : compact({
              outcome: updateOutcome,
              from: str(line, 'oldVersion'),
              to: str(line, 'newVersion'),
            }),
    }),
  )
}

const count = (text: string, label: string): number => {
  const match = new RegExp(`^\\s*${label} \\((\\d+)\\)`, 'm').exec(text)
  return match?.[1] === undefined ? 0 : Number(match[1])
}

/**
 * `claude plugin details <id>` (text only). It reports "Hooks (0)" for a mod
 * (it doesn't count function hooks), so modmgr reads only the other counts and the token cost from it.
 */
export const parseDetails = (run: CliRun): Result<Details> => {
  if (run.exitCode !== 0) return noJson(run)
  if (!/Component inventory/.test(run.stdout)) return fail('parse', 'details has no inventory')
  const tokens = /Always-on:\s*~?([\d,]+)\s*tok/.exec(run.stdout)?.[1]
  return ok(
    compact({
      skills: count(run.stdout, 'Skills'),
      agents: count(run.stdout, 'Agents'),
      hooks: count(run.stdout, 'Hooks'),
      mcp: count(run.stdout, 'MCP servers'),
      lsp: count(run.stdout, 'LSP servers'),
      tokens: tokens === undefined ? undefined : Number(tokens.replace(/,/g, '')),
    }),
  )
}

